content.content:
1	// A compact, chat-owned account of the setup: what the chat asked for, the
2	// selected presets, how the agent means to print (its plan's headline), and
3	// the estimates. Native code supplies the facts; this page presents them.
4	// The settings that differ from the presets are on the setup page.
5	
6	import { ReactNode, useState } from 'react';
7	import { ChangeInfo, SliceEstimateInfo, WorkspaceContext } from '../bridge/protocol';
8	
9	export interface SetupCardProps {
10	  context: WorkspaceContext | null;
11	  working?: boolean;
12	  historical?: boolean;
13	  savedAt?: string;
14	  agentAvailable?: boolean;
15	  changes?: ChangeInfo[];
16	  now?: number;
17	  estimateBefore?: SliceEstimateInfo | null;
18	  sent?: { at: string; printer: string };
19	  attention?: Finding[];
20	  onCompute?: () => void;
21	  onUndo?: (changeSeq: number) => void;
22	  onViewSetup?: () => void;
23	}
24	
25	export function formatPrintTime(seconds: number): string {
26	  const minutes = Math.round(seconds / 60);
27	  if (minutes < 60) return `~${minutes} min`;
28	  return `~${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
29	}
30	
31	export function formatGrams(grams: number): string {
32	  return `${grams < 10 ? Math.round(grams * 10) / 10 : Math.round(grams)} g`;
33	}
34	
35	export function formatCost(cost: number, currency: string): string {
36	  if (currency) {
37	    try {
38	      return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(cost);
39	    } catch {
40	      // An unknown regional code does not make the native amount disappear.
41	    }
42	  }
43	  return `cost ${cost.toFixed(2)}`;
44	}
45	
46	export function formatMoment(value: string | undefined): string {
47	  if (!value) return '';
48	  const date = new Date(value);
49	  if (Number.isNaN(date.getTime())) return value;
50	  return date.toLocaleString(undefined, {
51	    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false,
52	  });
53	}
54	
55	export const RECENT_CHANGE_MS = 60000;
56	
57	export interface EstimateView {
58	  heading: string;
59	  metrics: { icon: string; text: string }[];
60	  cost: string;
61	  plate: string;
62	  description: string;
63	  status: 'current' | 'recomputing' | 'stale' | 'none';
64	  sliced: boolean;
65	}
66	
67	export function estimateView(context: WorkspaceContext): EstimateView {
68	  const plate = context.plates.find((item) => item.active);
69	  const view: EstimateView = {
70	    heading: '', metrics: [], cost: '', plate: plate?.name ?? '', description: '', status: 'none', sliced: !!plate?.sliced,
71	  };
72	  if (!plate) return { ...view, description: 'Estimate unavailable' };
73	  const estimate = plate.estimate;
74	  const scoped = (text: string) => plate.name ? `${text} · ${plate.name}` : text;
75	  const metrics: EstimateView['metrics'] = [];
76	  if (estimate && (estimate.timeAvailable ?? estimate.printTimeSeconds > 0))
77	    metrics.push({ icon: 'clock', text: formatPrintTime(estimate.printTimeSeconds) });
78	  if (estimate && (estimate.materialAvailable ?? estimate.materialGrams > 0))
79	    metrics.push({ icon: 'package', text: formatGrams(estimate.materialGrams) });
80	  if (plate.estimateStatus === 'recomputing')
81	    return { ...view, status: 'recomputing', heading: 'Time & material estimates recomputing…',
82	      description: scoped('Settings confirmed') };
83	  if (metrics.length === 0)
84	    return { ...view, description: scoped(plate.sliced ? 'Estimate unavailable' : 'Not sliced yet · estimates unavailable') };
85	  const cost = estimate && estimate.materialCost !== null && estimate.materialCost >= 0.005
86	    ? formatCost(estimate.materialCost, context.currency) : '';
87	  if (plate.estimateStatus === 'stale')
88	    return { ...view, status: 'stale', heading: 'Previous estimates · not current', metrics, cost };
89	  return { ...view, status: 'current', metrics, cost };
90	}
91	
92	export interface Finding { title: string; detail?: string; facts?: string[]; }
93	
94	export function deterministicAttention(context: WorkspaceContext): Finding[] {
95	  const review = context.printerReview;
96	  if (!review) return [];
97	  const priority: Record<string, number> = { filament: 0, nozzle: 1, model: 2, plate: 3 };
98	  const noun: Record<string, string> = { filament: 'material', nozzle: 'nozzle', model: 'printer', plate: 'build plate' };
99	  const when = formatMoment(review.observed?.observedAt);
100	  return [...review.mismatches].sort((a, b) => (priority[a.what] ?? 4) - (priority[b.what] ?? 4)).flatMap((mismatch) => {
101	    const thing = noun[mismatch.what] ?? 'printer setup';
102	    if (mismatch.source === 'device') {
103	      if (!when) return [];
104	      const facts = [`Setup: ${mismatch.configured}`, `Printer last reported: ${mismatch.observed}`, `Reported ${when}`];
105	      if (review.observed?.connection) facts.push(`Printer is ${review.observed.connection} now`);
106	      return [{ title: `Last reported ${thing} differs`,
107	        detail: `Setup uses ${mismatch.configured}. Printer last reported ${mismatch.observed}.`, facts }];
108	    }
109	    return [{ title: `Confirmed ${thing} differs`,
110	      detail: `Setup uses ${mismatch.configured}. You confirmed ${mismatch.observed}.`,
111	      facts: [`Setup: ${mismatch.configured}`, `You confirmed: ${mismatch.observed}`] }];
112	  });
113	}
114	
115	export function recentAgentChange(changes: ChangeInfo[] | undefined, now: number): ChangeInfo[] {
116	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
117	  const last = log.at(-1);
118	  if (!last || last.actor !== 'agent' || (last.kind !== 'setting' && last.kind !== 'step')) return [];
119	  const made = Date.parse(last.createdAt);
120	  if (!Number.isFinite(made) || now - made >= RECENT_CHANGE_MS || now < made) return [];
121	  let start = log.length - 1;
122	  while (start > 0 && log[start - 1].actor === 'agent' && log[start - 1].afterId === last.afterId &&
123	    (log[start - 1].kind === 'setting' || log[start - 1].kind === 'step')) start -= 1;
124	  return log.slice(start);
125	}
126	
127	export function handEdits(changes: ChangeInfo[] | undefined): ChangeInfo[] {
128	  const log = [...(changes ?? [])].sort((a, b) => a.seq - b.seq);
129	  let start = log.length;
130	  while (start > 0 && log[start - 1].actor === 'person' && log[start - 1].kind !== 'restore') start -= 1;
131	  const net = new Map<string, ChangeInfo>();
132	  for (const change of log.slice(start))
133	    if (change.kind === 'setting') net.set(change.key || change.label, change);
134	  return [...net.values()];
135	}
136	
137	function estimatePair(estimate: SliceEstimateInfo): string {
138	  return `${formatPrintTime(estimate.printTimeSeconds)} / ${formatGrams(estimate.materialGrams)}`;
139	}
140	
141	function plural(count: number, one: string, many: string): string {
142	  return `${count} ${count === 1 ? one : many}`;
143	}
144	
145	function shortPreset(name: string): string {
146	  const separator = name.indexOf(' @');
147	  return separator < 0 ? name : name.slice(0, separator);
148	}
149	
150	export function presetsLine(context: WorkspaceContext, title: string): string {
151	  const process = context.printer.process.trim();
152	  if (!process) return '';
153	  const filaments = context.setupIdentity?.filaments ?? [];
154	  const first = (filaments[0]?.preset || context.printer.filament).trim();
155	  const filament = first ? `${shortPreset(first)}${filaments.length > 1 ? ` +${filaments.length - 1}` : ''}` : '';
156	  const parts = title === process ? [filament] : [shortPreset(process), filament];
157	  return parts.filter(Boolean).join(' · ');
158	}
159	
160	// Objects that print with settings of their own. The headline cannot say so,
161	// and nothing else on the card does.
162	export function overrideObjectCount(context: WorkspaceContext): number {
163	  return new Set((context.appliedSetup?.localOverrides ?? [])
164	    .map((local) => local.object).filter((object): object is number => object !== undefined)).size;
165	}
166	
167	export interface SetupPresentationOptions {
168	  historical?: boolean;
169	  working?: boolean;
170	  agentAvailable?: boolean;
171	  changes?: ChangeInfo[];
172	  now?: number;
173	  sent?: { at: string; printer: string };
174	  savedAt?: string;
175	}
176	
177	// What the card and the setup page both say about themselves: their label,
178	// their one state, their title. Conversation status outranks live activity: a
179	// saved card is never working, whatever the active chat happens to be doing.
180	export function setupPresentation(context: WorkspaceContext, options: SetupPresentationOptions = {}) {
181	  const historical = !!options.historical;
182	  const working = !!options.working && !historical;
183	  const estimate = estimateView(context);
184	  const intent = context.setupIntent.trim();
185	  const title = intent || context.printer.process.trim();
186	  // Nothing vouches for this setup but the preset the person picked: no agent
187	  // is configured, or the host read no settings to compare with it.
188	  const noAgent = !historical && options.agentAvailable === false;
189	  if (noAgent || (!historical && !context.appliedSetup && !intent))
190	    return { label: 'Preset fallback', state: noAgent ? 'No agent' : null as ReactNode, title: context.printer.process.trim(),
191	      estimate, justChanged: [], edited: [], editedByYou: false, outOfDate: false, live: true, fallback: true, noAgent };
192	  const justChanged = historical ? [] : recentAgentChange(options.changes, options.now ?? Date.now());
193	  const edited = historical || working || justChanged.length > 0 ? [] : handEdits(options.changes);
194	  // "Edited by you" needs a setup the agent had a hand in; without one a
195	  // hand edit is simply how the project was made.
196	  const agentManaged = !!intent || (options.changes ?? []).some((change) => change.actor === 'agent');
197	  const editedByYou = edited.length > 0 && agentManaged;
198	  // Out of date stands the card down: it drops the accent, as a saved card
199	  // does, because it no longer vouches for the numbers under it.
200	  const outOfDate = estimate.status === 'stale' && !working && justChanged.length === 0 && !editedByYou;
201	  const saved = formatMoment(options.savedAt);
202	  const label = options.sent ? 'Saved sliced snapshot' : historical || outOfDate ? 'Earlier setup' : 'Setup summary';
203	  const state: ReactNode = historical
204	    ? options.sent ? 'Sliced & sent' : estimate.status === 'stale' ? 'Out of date'
205	      : saved ? <><span className="jp-icon jp-icon-clock" aria-hidden="true" />Saved {saved}</> : null
206	    : working ? 'Agent working' : justChanged.length > 0 ? 'Updated'
207	    : estimate.status === 'recomputing' ? 'Confirmed' : editedByYou ? 'Edited by you'
208	    : outOfDate ? 'Out of date' : estimate.status === 'none' && !estimate.sliced ? 'Not sliced' : 'Current';
209	  return { label, state, title, estimate, justChanged, edited, editedByYou, outOfDate, live: !historical && !outOfDate,
210	    fallback: false, noAgent: false };
211	}
212	
213	function Metrics({ estimate }: { estimate: EstimateView }) {
214	  return <div className="current-setup-metrics">
215	    {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
216	      <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
217	    {estimate.plate && <span className="current-setup-metric">
218	      <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
219	    {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
220	  </div>;
221	}
222	
223	function Attention({ findings }: { findings: Finding[] }) {
224	  const [open, setOpen] = useState(false);
225	  if (findings.length === 0) return null;
226	  const first = findings[0];
227	  const reviewable = findings.length > 1 || (first.facts ?? []).length > 0;
228	  const subject = findings.length > 1 ? plural(findings.length, 'finding', 'findings')
229	    : first.title.replace(/^(Last reported|Confirmed) | differs$/g, '');
230	  return <>
231	    <div className="current-setup-attention">
232	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />{first.title}</p>
233	      {first.detail && <p className="current-setup-line">{first.detail}</p>}
234	      {reviewable && <button type="button" className="current-setup-link" aria-expanded={open} onClick={() => setOpen(!open)}>
235	        Review {subject}</button>}
236	      {open && <ul className="current-setup-findings">{findings.map((finding, index) => <li key={index}>
237	        {findings.length > 1 && <strong>{finding.title}</strong>}
238	        {(finding.facts ?? []).map((fact) => <span key={fact}>{fact}</span>)}
239	      </li>)}</ul>}
240	    </div>
241	    <hr className="current-setup-divider" />
242	  </>;
243	}
244	
245	export function SetupCard({ context, working: busy = false, historical = false, savedAt, agentAvailable = true,
246	  changes, now = Date.now(), estimateBefore, sent, attention = [], onCompute, onUndo, onViewSetup }: SetupCardProps) {
247	  if (!context) return null;
248	  // A saved card is never working, whatever the active chat happens to be
249	  // doing.
250	  const working = busy && !historical;
251	  const ariaLabel = historical ? 'Earlier setup — saved with this conversation' : 'Current setup';
252	  const presentation = setupPresentation(context, { historical, working, agentAvailable, changes, now, sent, savedAt });
253	
254	  if (presentation.fallback) {
255	    const { estimate, title } = presentation;
256	    return <section className="current-setup current-setup--live" data-testid="current-setup" aria-label={ariaLabel}>
257	      <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
258	        {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
259	      {title && <h2 className="current-setup-title" title={title}>{title}</h2>}
260	      {presentation.noAgent ? <p className="current-setup-line">No agent configured · using the selected preset.</p>
261	        : estimate.metrics.length > 0 ? <Metrics estimate={estimate} />
262	        : <p className="current-setup-line">{estimate.description}</p>}
263	    </section>;
264	  }
265	
266	  const { estimate, justChanged, edited, editedByYou, outOfDate } = presentation;
267	  // The plan's headline in every state the card has: the state label and the
268	  // notices say how far the card can be trusted. With no plan pinned there is
269	  // no line at all.
270	  const headline = context.planHeadline.trim();
271	  const objects = overrideObjectCount(context);
272	  const presets = presetsLine(context, presentation.title);
273	
274	  const withheld = editedByYou && estimate.status === 'stale';
275	  const heading = withheld ? '' : estimate.heading ? estimate.heading : estimate.metrics.length === 0 ? ''
276	    : sent ? 'Saved pre-slice estimates' : working ? 'Last confirmed estimates' : '';
277	  const description = withheld ? (estimate.plate ? `Estimate unavailable for these edits · ${estimate.plate}`
278	    : 'Estimate unavailable for these edits') : estimate.description;
279	  const canCompute = !historical && !working && !!onCompute && estimate.status === 'none';
280	  // What the card adds for the minute a change is new. The settings the
281	  // agent changed are not listed: the thread's change rows under its turn
282	  // name them, and the setup page lists every difference. A project step is
283	  // named here, and it is the one thing Orca can undo: its undo takes the top
284	  // of its own stack, and a preset edit is not on it.
285	  const last = justChanged.at(-1);
286	  const step = !working && last?.kind === 'step' ? last : undefined;
287	  const undoable = !!onUndo && !!step && context.history.canUndo;
288	  const plate = context.plates.find((item) => item.active);
289	  const after = plate?.estimate;
290	  const estimateDelta = justChanged.length > 0 && estimateBefore && after && estimate.status === 'current' &&
291	    (estimateBefore.printTimeSeconds !== after.printTimeSeconds || estimateBefore.materialGrams !== after.materialGrams)
292	    ? `Estimate: ${estimatePair(estimateBefore)} → ${estimatePair(after)}` : '';
293	  const named = edited.slice(0, 2).map((change) => `${change.label} ${change.to || 'none'}`);
294	  const editedText = edited.length > 2 ? `${named.join(', ')} and ${plural(edited.length - 2, 'more setting', 'more settings')}`
295	    : named.join(' and ');
296	  const findings = [...deterministicAttention(context), ...attention];
297	
298	  return <section className={presentation.live ? 'current-setup current-setup--live' : 'current-setup'}
299	    data-testid="current-setup" aria-label={ariaLabel} aria-busy={working || undefined}>
300	    <div className="current-setup-header"><span className="current-setup-label">{presentation.label}</span>
301	      {presentation.state && <span className="current-setup-state">{presentation.state}</span>}</div>
302	    {presentation.title && <h2 className="current-setup-title" title={presentation.title}>{presentation.title}</h2>}
303	    {presets && <p className="current-setup-line current-setup-line--single" title={presets}>{presets}</p>}
304	    {headline && <p className="current-setup-strategy">{headline}</p>}
305	    {objects > 0 && <p className="current-setup-note">
306	      {plural(objects, 'object with overrides', 'objects with overrides')}</p>}
307	    {heading && <p className="current-setup-heading">{heading}</p>}
308	    {!withheld && estimate.metrics.length > 0 && <Metrics estimate={estimate} />}
309	    {description && <p className="current-setup-line">{description}</p>}
310	    {sent && estimate.metrics.length > 0 && <p className="current-setup-line">Actual time &amp; material unavailable.</p>}
311	    {canCompute && <button type="button" className="current-setup-link" onClick={onCompute}>Compute estimates</button>}
312	    <hr className="current-setup-divider" />
313	    {working && <><p className="current-setup-line">Agent is applying and evaluating changes…<br />
314	      Shown settings remain the last confirmed setup.</p><hr className="current-setup-divider" /></>}
315	    {!working && (step || estimateDelta) && <>
316	      {step && <p className="current-setup-line">{step.label || 'Object settings changed'}</p>}
317	      {estimateDelta && <p className="current-setup-line">{estimateDelta}</p>}
318	      {undoable && <button type="button" className="current-setup-link" onClick={() => onUndo!(step!.seq)}>Undo</button>}
319	      <hr className="current-setup-divider" />
320	    </>}
321	    {outOfDate && <><div className="current-setup-attention">
322	      <p className="current-setup-warning"><span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />
323	        {historical ? 'These estimates were already out of date when saved.' : 'Estimates no longer match the current project.'}</p>
324	      {plate?.invalidatedBy && <p className="current-setup-line">{plate.invalidatedBy}</p>}
325	      {!historical && onCompute && <button type="button" className="current-setup-link" onClick={onCompute}>
326	        Refresh setup &amp; recompute</button>}
327	    </div><hr className="current-setup-divider" /></>}
328	    {editedByYou && <><p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
329	      <span>You set {editedText} outside the agent. Your current settings are preserved.</span></p>
330	      <hr className="current-setup-divider" /></>}
331	    <Attention findings={findings} />
332	    <button type="button" className="current-setup-link" onClick={onViewSetup}>View setup</button>
333	    {historical && <><hr className="current-setup-divider" />
334	      {sent && <p className="current-setup-sent">{[formatMoment(sent.at), sent.printer && `sent to ${sent.printer}`]
335	        .filter(Boolean).join(' · ')}</p>}
336	      <p className="current-setup-info"><span className="jp-icon jp-icon-info" aria-hidden="true" />
337	        <span>{sent ? 'Saved snapshot.' : 'Saved with this chat.'} The canvas shows your current project.</span></p>
338	    </>}
339	  </section>;
