47	declare global {
48	  interface Window {
49	    // Deterministic hooks for the native shell harness; harmless in
50	    // production and never a second control path for users.
51	    __jusprinTest?: {
52	      send(text: string): void;
53	      cancelTool(actionId: string): void;
54	      createConversation(): void;
55	      switchConversation(conversationId: string): void;
56	      renameConversation(conversationId: string, title: string): void;
57	      deleteConversation(conversationId: string): void;
58	      setDraft(text: string): void;
59	      openSetup(): void;
60	      checkKey(provider: string, apiKey: string): void;
61	      attach(name: string, dataBase64: string, mime?: string): void;
62	      removeAttachment(attachmentId: string): void;
63	      state(): AgentUiState;
64	    };
65	  }
66	}
67	
68	export interface AppProps {
69	  getTransport: () => Transport | null;
70	  handshakeTimeoutMs?: number;
71	  transportRetryMs?: number;
72	  transportRetryLimit?: number;
73	  draftDebounceMs?: number;
74	  // A throwaway, setup-only instance (e.g. embedded in the Add a printer
75	  // dialog rather than the docked panel): show only the setup sub-component,
76	  // never the conversation header, chat list, or composer around it.
77	  embedded?: boolean;
78	  // Temporary printer task chat: the same thread and composer, with the
79	  // printer session's own header and cards instead of the project's.
80	  printerPanel?: boolean;
81	}
82	
83	const errorTitles: Partial<Record<ConnectionState, string>> = {
84	  'no-transport': 'The Agent panel has no connection to JusPrin',
85	  timeout: 'The Agent panel could not reach JusPrin',
86	  incompatible: 'This Agent panel does not match this JusPrin build',
87	};
88	
89	export function App({
90	  getTransport,
91	  handshakeTimeoutMs,
92	  transportRetryMs,
93	  transportRetryLimit,
94	  draftDebounceMs,
95	  embedded,
96	  printerPanel,
97	}: AppProps) {
98	  const [state, dispatch] = useReducer(reducer, initialState);
99	  const stateRef = useRef<AgentUiState>(state);
100	  stateRef.current = state;
101	
102	  // Which setup screen the dock is showing. This is page-local on purpose:
103	  // the host cares which credentials it was asked to check, not which panel
104	  // is on screen, so navigating setup costs no bridge traffic.
105	  const [setupScreen, setSetupScreen] = useState<'offer' | 'chooser' | 'apiKey' | 'localTool'>('offer');
106	  const [view, setView] = useState<'chat' | 'list' | 'setup' | 'setupDetails'>('chat');
107	  const [commandError, setCommandError] = useState<string | null>(null);
108	  const [confirmChatRestore, setConfirmChatRestore] = useState(false);
109	  const setupReturn = useRef<'chat' | 'list'>('chat');
110	  // The one-time confirmation after setup succeeds. The page knows what it
111	  // just submitted, so this needs nothing from the host.
112	  const [connected, setConnected] = useState<{ provider: string; warning?: string } | null>(null);
113	
114	  const client = useMemo(() => {
115	    const created: BridgeClient = new BridgeClient({
116	      getTransport,
117	      handshakeTimeoutMs,
118	      transportRetryMs,
119	      transportRetryLimit,
120	      onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
121	      onEnvelope: (envelope: Envelope) => {
122	        if (envelope.type === 'bridge_error') {
123	          const payload = envelope.payload as { code?: string; message?: string };
124	          setCommandError(payload.message ?? 'The action could not be completed.');
125	          // The host restarts after a reload on its side; if it forgot us,
126	          // simply shake hands again.
127	          if (payload.code === 'handshake_required') created.retry();
