import { useEffect, useMemo, useReducer, useRef, useState } from 'react';
import { BridgeClient, ConnectionState, Transport } from './bridge/client';
import { AttachmentPickKind, AttachmentSource, Envelope, SliceEstimateInfo } from './bridge/protocol';
import { AgentUiState, initialState, reducer } from './state/store';
import { applyAppearance } from './tokens';
import { RECENT_CHANGE_MS, SetupCard } from './components/SetupCard';
import { SetupPage, SetupPageHeader } from './components/SetupPage';
import { AgentPaneToggle, ChatHeader, ChatList, Dialog } from './components/ChatNavigation';
import { MessageList } from './components/MessageList';
import { Composer } from './components/Composer';
import { PrinterCredentialForm } from './components/PrinterPanel';
import { printerInstructions } from './printerInstructions';
import { filamentInstructions } from './filamentInstructions';
import { skills } from './skills';
import { projectInstructions } from './projectInstructions';
import { opening, placeholder } from './printerWords';
import {
  AgentNotConfiguredHeader,
  AgentNotConfiguredPane,
  BridgeErrorPane,
  ConnectingPane,
} from './components/Panels';
import { ConnectedBanner, DEFAULT_PROVIDER, SetupApiKey, SetupChooser } from './components/Setup';
import { SetupLocalTool } from './components/SetupLocalTool';

let clientMessageCounter = 0;
function nextClientMessageId(): string {
  clientMessageCounter += 1;
  return `c-${clientMessageCounter}-${Math.random().toString(36).slice(2, 10)}`;
}

let clientAttachmentCounter = 0;
function nextClientAttachmentId(): string {
  clientAttachmentCounter += 1;
  return `ca-${clientAttachmentCounter}-${Math.random().toString(36).slice(2, 10)}`;
}

function readAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
    reader.onerror = () => reject(reader.error ?? new Error('read failed'));
    reader.readAsDataURL(file);
  });
}

declare global {
  interface Window {
    // Deterministic hooks for the native shell harness; harmless in
    // production and never a second control path for users.
    __jusprinTest?: {
      send(text: string): void;
      cancelTool(actionId: string): void;
      createConversation(): void;
      switchConversation(conversationId: string): void;
      renameConversation(conversationId: string, title: string): void;
      deleteConversation(conversationId: string): void;
      setDraft(text: string): void;
      openSetup(): void;
      checkKey(provider: string, apiKey: string): void;
      attach(name: string, dataBase64: string, mime?: string): void;
      removeAttachment(attachmentId: string): void;
      state(): AgentUiState;
    };
  }
}

export interface AppProps {
  getTransport: () => Transport | null;
  handshakeTimeoutMs?: number;
  transportRetryMs?: number;
  transportRetryLimit?: number;
  draftDebounceMs?: number;
  // A throwaway, setup-only instance (e.g. embedded in the Add a printer
  // dialog rather than the docked panel): show only the setup sub-component,
  // never the conversation header, chat list, or composer around it.
  embedded?: boolean;
  // Temporary printer task chat: the same thread and composer, with the
  // printer session's own header and cards instead of the project's.
  printerPanel?: boolean;
}

const errorTitles: Partial<Record<ConnectionState, string>> = {
  'no-transport': 'The Agent panel has no connection to JusPrin',
  timeout: 'The Agent panel could not reach JusPrin',
  incompatible: 'This Agent panel does not match this JusPrin build',
};

export function App({
  getTransport,
  handshakeTimeoutMs,
  transportRetryMs,
  transportRetryLimit,
  draftDebounceMs,
  embedded,
  printerPanel,
}: AppProps) {
  const [state, dispatch] = useReducer(reducer, initialState);
  const stateRef = useRef<AgentUiState>(state);
  stateRef.current = state;

  // Which setup screen the dock is showing. This is page-local on purpose:
  // the host cares which credentials it was asked to check, not which panel
  // is on screen, so navigating setup costs no bridge traffic.
  const [setupScreen, setSetupScreen] = useState<'offer' | 'chooser' | 'apiKey' | 'localTool'>('offer');
  const [view, setView] = useState<'chat' | 'list' | 'setup' | 'setupDetails'>('chat');
  const [commandError, setCommandError] = useState<string | null>(null);
  const [confirmChatRestore, setConfirmChatRestore] = useState(false);
  const setupReturn = useRef<'chat' | 'list'>('chat');
  // The one-time confirmation after setup succeeds. The page knows what it
  // just submitted, so this needs nothing from the host.
  const [connected, setConnected] = useState<{ provider: string; warning?: string } | null>(null);

  const client = useMemo(() => {
    const created: BridgeClient = new BridgeClient({
      getTransport,
      handshakeTimeoutMs,
      transportRetryMs,
      transportRetryLimit,
      onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
      onEnvelope: (envelope: Envelope) => {
        if (envelope.type === 'bridge_error') {
          const payload = envelope.payload as { code?: string; message?: string };
          setCommandError(payload.message ?? 'The action could not be completed.');
          // The host restarts after a reload on its side; if it forgot us,
          // simply shake hands again.
          if (payload.code === 'handshake_required') created.retry();
        }
        dispatch({ kind: 'host', envelope });
      },
    });
    return created;
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  // The printer panel's first line, which the model is shown as having said:
  // written here, posted by the app, once per session. Before the
  // instructions, so the thread opens with it whatever is sent next.
  const sentOpening = useRef(false);
  useEffect(() => {
    if (!printerPanel || !state.session || state.connection !== 'connected') return;
    if (sentOpening.current || state.messages.length > 0) return;
    sentOpening.current = true;
    client.send('printer_opening', { text: opening(state.session) });
  }, [printerPanel, state.session, state.connection, state.messages.length, client]);

  // The printer panel writes the model's instructions from the facts the app
  // sends; the app holds them for the session's requests. Sent again only
  // when the words change, such as after a change to the printer.
  const sentInstructions = useRef<string | null>(null);
  useEffect(() => {
    if (!printerPanel || !state.session || state.connection !== 'connected') return;
    const text = printerInstructions(state.session);
    if (text === sentInstructions.current) return;
    sentInstructions.current = text;
    client.send('printer_instructions', { text });
  }, [printerPanel, state.session, state.connection, client]);

  // The project assistant's whole prompt; the app holds it in the project
  // session and sends it with every request, and starts no project turn
  // without it. Sent on every connection (a reload reconnects) and again
  // only if the words change.
  const sentProjectInstructions = useRef<string | null>(null);
  useEffect(() => {
    if (printerPanel || embedded || state.connection !== 'connected') {
      if (state.connection !== 'connected') sentProjectInstructions.current = null;
      return;
    }
    const text = projectInstructions();
    if (text === sentProjectInstructions.current) return;
    sentProjectInstructions.current = text;
    client.send('project_instructions', { text });
  }, [printerPanel, embedded, state.connection, client]);

  // The project skills: situational text the app adds to one request when
  // its trigger fires (skills/*/SKILL.md). Once per connection: a reload
  // reconnects, and the words do not change. The app starts no project turn
  // before it has them.
  const sentSkills = useRef(false);
  useEffect(() => {
    if (printerPanel || embedded || state.connection !== 'connected') {
      if (state.connection !== 'connected') sentSkills.current = false;
      return;
    }
    if (sentSkills.current) return;
    sentSkills.current = true;
    client.send('skills', { skills });
  }, [printerPanel, embedded, state.connection, client]);

  // The filament chat's instructions, likewise: written from the facts the
  // app sends, sent again when they change, such as after a save as a copy.
  const sentFilamentInstructions = useRef<string | null>(null);
  useEffect(() => {
    if (!state.filamentSession || state.connection !== 'connected') return;
    const text = filamentInstructions(state.filamentSession);
    if (text === sentFilamentInstructions.current) return;
    sentFilamentInstructions.current = text;
    client.send('filament_instructions', { text });
  }, [state.filamentSession, state.connection, client]);

  // The printer panel's Back asks first once leaving would lose something:
  // what the person said, or what they are about to send. The composer's
  // words are mirrored here, not in state, so typing renders nothing more.
  const [confirmPrinterClose, setConfirmPrinterClose] = useState(false);
  const printerDraft = useRef('');

  useEffect(() => { setView('chat'); setCommandError(null); }, [state.context?.sessionId]);
  useEffect(() => { if (state.navigation.focused) setView('chat'); }, [state.navigation.focused]);

  useEffect(() => {
    if (state.needsResync) {
      client.send('state_request', {});
      dispatch({ kind: 'resync-requested' });
    }
  }, [state.needsResync, client]);

  // The composer shows staged attachments plus any that failed to attach, so a
  // rejection stays visible until the user dismisses it; only staged ones are
  // actually sent.
  const stagedAttachments = state.attachments.filter(
    (attachment) => attachment.state === 'staged' || attachment.state === 'error',
  );

  const sendMessage = (text: string, includeStagedAttachments = true) => {
    // From the ref, not this render: the test hook keeps the first render's
    // sendMessage, which would otherwise never see a later attachment.
    const attachmentIds = includeStagedAttachments
      ? stateRef.current.attachments.filter((a) => a.state === 'staged').map((a) => a.id)
      : [];
    client.send('user_message', { clientMessageId: nextClientMessageId(), text, attachmentIds,
      conversationId: stateRef.current.activeConversationId });
  };

  const attachFiles = (files: File[], source: AttachmentSource) => {
    for (const file of files) {
      readAsDataUrl(file)
        .then((dataUrl) => {
          client.send('attach_file', {
            clientAttachmentId: nextClientAttachmentId(),
            name: file.name,
            mime: file.type,
            source,
            dataBase64: dataUrl,
          });
        })
        .catch(() => {
          // A file the browser could not read never becomes a staged
          // attachment; the host only sees files it can decode.
        });
    }
  };

  // The host's own file dialog, filtered to one kind, where the host has one.
  const pickFiles = state.hostCapabilities.includes('native_file_picker')
    ? (kind: AttachmentPickKind) => client.send('pick_attachment', { kind })
    : undefined;

  const removeAttachment = (attachmentId: string) => {
    client.send('remove_attachment', { attachmentId });
  };

  // A printer access code goes straight to the printer session and never
  // enters a tool activity or chat.
  const connectPrinter = (actionId: string, credential: string) => {
    client.send('printer_action', { action: 'connect', actionId, credential });
  };

  const sendToolCancel = (actionId: string) => {
    client.send('tool_cancel', { actionId });
  };

  const sendWorkCancel = (id: string) => {
    client.send('work_cancel', { id });
  };

  const checkKey = (provider: string, apiKey: string) => {
    client.send('setup_check_key', { provider, apiKey });
  };

  const cancelCheck = () => {
    client.send('setup_cancel', {});
  };

  // The one way into setup: the dock's own button, and the host when another
  // JusPrin surface sends the person here.
  const openSetup = () => { setupReturn.current = 'chat'; setSetupScreen('chooser'); setView('setup'); };

  useEffect(() => {
    if (state.setupRequests > 0) openSetup();
  }, [state.setupRequests]);

  useEffect(() => {
    if (state.setup.phase !== 'verified') return;
    // The host installs the verified service right after saying so, so the
    // dock is about to become a working chat; carry the confirmation across.
    // The key screen stays up until that happens, so the round-trip the check
    // measured is actually readable rather than flashing past.
    setConnected({ provider: state.setup.provider ?? DEFAULT_PROVIDER, warning: state.setup.warning });
    if (state.agentStatus === 'ready') setView('chat');
  }, [state.setup.phase, state.setup.provider, state.setup.warning, state.agentStatus]);

  useEffect(() => {
    // A connected Agent replaces the setup surface entirely; if the dock ever
    // returns to being unconfigured it starts from the offer, not mid-flow.
    if (state.agentStatus === 'ready') setSetupScreen('offer');
  }, [state.agentStatus]);

  useEffect(() => {
    window.__jusprinTest = {
      send: sendMessage,
      cancelTool: sendToolCancel,
      createConversation: () => client.send('create_conversation', {}),
      switchConversation: (conversationId: string) => client.send('switch_conversation', { conversationId }),
      renameConversation: (conversationId, title) => client.send('rename_conversation', { conversationId, title }),
      deleteConversation: (conversationId) => client.send('delete_conversation', { conversationId }),
      setDraft: (text: string) => client.send('draft_update', { text }),
      openSetup,
      checkKey,
      attach: (name: string, dataBase64: string, mime?: string) =>
        client.send('attach_file', {
          clientAttachmentId: nextClientAttachmentId(),
          name,
          mime: mime ?? '',
          source: 'picker',
          dataBase64,
        }),
      removeAttachment,
      state: () => stateRef.current,
    };
    return () => {
      delete window.__jusprinTest;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const viewed = state.viewedConversationId || state.activeConversationId;
    if (state.connection !== 'connected' || viewed !== state.activeConversationId ||
        view !== 'chat' || !state.context) return;
    const timer = window.setInterval(() => client.send('state_request', {}), 30000);
    return () => window.clearInterval(timer);
  }, [client, state.connection, state.viewedConversationId, state.activeConversationId, view, state.context?.sessionId]);

  // "Just changed" is a window of time, so something has to end it: one
  // timer per newest change, set for the moment that change stops being new.
  const [now, setNow] = useState(() => Date.now());
  const newestChange = state.changes.at(-1);
  useEffect(() => {
    setNow(Date.now());
    if (!newestChange) return;
    const left = Date.parse(newestChange.createdAt) + RECENT_CHANGE_MS - Date.now();
    if (!Number.isFinite(left) || left <= 0) return;
    const timer = window.setTimeout(() => setNow(Date.now()), left + 50);
    return () => window.clearTimeout(timer);
  }, [newestChange?.seq, newestChange?.createdAt]);

  // The pair behind "Estimate: a → b": the plate's last current estimate, and
  // the one that was in force when the newest change arrived. Both are native
  // figures for the same plate; nothing here is computed.
  const activePlate = state.context?.plates.find((plate) => plate.active);
  const lastEstimate = useRef<{ plateId: string; estimate: SliceEstimateInfo } | null>(null);
  const beforeChange = useRef<{ seq: number; plateId: string; estimate: SliceEstimateInfo } | null>(null);
  useEffect(() => {
    if (!newestChange || beforeChange.current?.seq === newestChange.seq) return;
    beforeChange.current = lastEstimate.current ? { seq: newestChange.seq, ...lastEstimate.current } : null;
  }, [newestChange?.seq]);
  useEffect(() => {
    if (activePlate?.estimate && activePlate.estimateStatus === 'current')
      lastEstimate.current = { plateId: activePlate.id, estimate: activePlate.estimate };
  }, [activePlate?.id, activePlate?.estimate, activePlate?.estimateStatus]);

  if (state.connection === 'connecting') return <div className="app"><ConnectingPane /></div>;

  if (state.connection !== 'connected') {
    return (
      <div className="app">
        <BridgeErrorPane
          title={errorTitles[state.connection] ?? 'The Agent panel could not connect'}
          detail={state.connectionDetail}
          diagnostics={state.diagnostics}
          onRetry={() => client.retry()}
        />
      </div>
    );
  }

  const unavailable = state.agentStatus === 'unavailable';
  // The printer greeting and a focused filament context note must not hide
  // setup. File reports are notes, so they do not turn an otherwise empty
  // project conversation into history. Other saved history stays visible.
  const onlyFileReports = state.messages.every((message) => message.role === 'note' && !!message.fileReport);
  const fileReportNotes = state.messages.flatMap((message) =>
    message.role === 'note' && message.fileReport && message.fileReportCard
      ? [{ id: message.id, report: message.fileReport }]
      : [],
  );
  const notConfigured = unavailable && (printerPanel || state.navigation.focused || onlyFileReports);
  const streaming = state.streamingMessageId !== null;
  const busy = streaming || state.conversationBusy || state.projectChatBlocked;
  const viewedId = state.viewedConversationId || state.activeConversationId;
  const viewedChat = state.conversations.find((chat) => chat.id === viewedId);
  const historical = viewedId !== state.activeConversationId;
  const resumeStatus = state.chatResume.status;
  // What the notice on an earlier chat says depends on what its checkpoint is
  // worth: only a project that really moved on is described as updated.
  const boundary = resumeStatus === 'changed'
    ? 'There have been project updates since this chat. Restore its saved project version to continue.'
    : resumeStatus === 'unchanged'
      ? 'This chat is inactive. Resume from its saved setup to continue.'
      : 'This chat has no recoverable project checkpoint. Its saved state is missing or corrupt.';
  const returnToActiveChat = () => {
    client.send('switch_conversation', { conversationId: state.activeConversationId });
    setView('chat');
  };
  const askCurrentChat = () => {
    const latest = [...stateRef.current.messages].reverse().find((message) => message.text.trim());
    const excerpt = latest ? `\nExcerpt: “${latest.text.trim().slice(0, 600)}”` : '';
    const reference = `From earlier chat “${viewedChat?.title || viewedId}”${state.chatResume.savedAt ?
      ` (saved ${state.chatResume.savedAt})` : ''}:${excerpt}\n\nWhat should we do with this in the current project?`;
    client.send('switch_conversation', { conversationId: state.activeConversationId });
    client.send('draft_update', { append: reference });
    client.send('state_request', {});
    setView('chat');
  };
  const resumeChat = () => {
    if (resumeStatus === 'changed') { setConfirmChatRestore(true); return; }
    if (resumeStatus === 'unchanged') client.send('restore_conversation', {
      conversationId: viewedId, activeConversationId: state.activeConversationId, docRevision: state.docRevision,
    });
  };
  // The notice on an earlier chat: why it cannot continue as it is, and the
  // ways on. It sits in the composer's band, above the field it has locked.
  const projectUpdates = historical && <div className="project-updates" role="note">
    <p>{boundary}</p>
    <div className="project-updates-actions">
      {resumeStatus !== 'unavailable' && <button type="button" className="primary"
        disabled={busy || state.projectChatBlocked} onClick={resumeChat}>{resumeStatus === 'changed' ? 'Restore and resume' : 'Resume saved setup'}</button>}
      <button type="button" className="project-updates-link" onClick={returnToActiveChat}>Return to active chat</button>
      <button type="button" className="project-updates-link" onClick={askCurrentChat}>Ask current chat about this</button>
    </div>
  </div>;
  const blockedAlert = state.projectChatBlocked && <div className="composer-alert" role="alert">
    Project restoration needs recovery. This chat cannot run project actions.
  </div>;
  const cardContext = historical ? state.chatResume.summary ?? null : state.context;
  // A saved summary belongs to a send when this chat sent the plate it shows.
  const sentBuild = historical ? [...state.builds].reverse().find((record) => record.conversationId === viewedId &&
    !!record.sentAt && record.plateIndex === cardContext?.plates.findIndex((plate) => plate.active)) : undefined;
  // The card sits in its own pinned band above the thread, as the design has
  // it: the band is the canvas the tinted card sits on.
  const setupCard = view === 'chat' && cardContext && <div className="pinned-setup">
    <SetupCard context={cardContext} historical={historical} savedAt={historical ? state.chatResume.savedAt : undefined}
      agentAvailable={!unavailable} working={!historical && busy}
      changes={historical ? undefined : state.changes.filter((change) => change.conversationId === viewedId)}
      now={now}
      estimateBefore={!historical && beforeChange.current?.seq === newestChange?.seq &&
        beforeChange.current?.plateId === activePlate?.id ? beforeChange.current?.estimate : null}
      sent={sentBuild?.sentAt ? { at: sentBuild.sentAt, printer: sentBuild.printer } : undefined}
      onCompute={historical ? undefined : () => {
        const current = stateRef.current.context;
        const plate = current?.plates.find((item) => item.active);
        if (current && plate) client.send('shell_action', {
          action: 'compute_setup_estimates', sessionId: current.sessionId, plateId: plate.id,
        });
      }}
      onUndo={historical ? undefined : (changeSeq) => {
        const current = stateRef.current.context;
        if (current) client.send('shell_action', { action: 'undo_setup_change', sessionId: current.sessionId, changeSeq });
      }}
      onViewSetup={() => setView('setupDetails')} />
  </div>;
  const pendingAction = state.toolActivities.some((activity) =>
    state.messages.some((message) => message.id === activity.correlationId) &&
    activity.state === 'running');
  const createChat = () => { client.send('create_conversation', {}); setView('chat'); };
  const collapseAgentPane = () => client.send('shell_action', { action: 'collapse_agent_pane' });
  const returnToWorkspace = () => client.send('shell_action', { action: 'return_to_workspace' });
  const closeSetup = () => { cancelCheck(); setSetupScreen('offer'); setView(setupReturn.current); };

  const errorNotice = commandError && <div className="chat-error" role="alert">
    <span>{commandError}</span><button className="icon" aria-label="Dismiss error" title="Dismiss error" onClick={() => setCommandError(null)}><span className="jp-icon jp-icon-close" aria-hidden="true" /></button>
  </div>;

  const chatList = <ChatList conversations={state.conversations} activeId={state.activeConversationId} busy={busy}
      onSwitch={(conversationId) => {
        if (conversationId !== viewedId) client.send('switch_conversation', { conversationId });
        setView('chat');
      }} onCreate={createChat} agentUnavailable={unavailable} onConfigure={() => {
        setupReturn.current = 'list'; setSetupScreen('chooser'); setView('setup');
      }} onCollapse={collapseAgentPane} />;

  // The dock body is one of three things: the conversation, the offer, or a
  // setup screen. Setup replaces the body rather than covering it, so backing
  // out returns to exactly what was there before.
  const body = () => {
    if (!embedded && view === 'setupDetails' && cardContext)
      return <SetupPage context={cardContext} historical={historical} working={!historical && busy} agentAvailable={!unavailable}
        changes={historical ? undefined : state.changes.filter((change) => change.conversationId === viewedId)}
        now={now} savedAt={historical ? state.chatResume.savedAt : undefined}
        sent={sentBuild?.sentAt ? { at: sentBuild.sentAt, printer: sentBuild.printer } : undefined} />;
    // An embedded, setup-only instance never has a conversation to show, so
    // it always renders one of the setup screens below regardless of view.
    if (!embedded && !notConfigured && view !== 'setup')
      return (
        <MessageList
          key={`messages-${state.context?.sessionId}-${viewedId}`}
          messages={state.messages}
          attachments={state.attachments}
          streamingMessageId={state.streamingMessageId}
          toolActivities={state.toolActivities}
          builds={historical ? state.builds.filter((record) => record.conversationId === viewedId) : state.builds}
          exportedCopies={historical ? state.exportedCopies.filter((record) => record.conversationId === viewedId) : state.exportedCopies}
          physicalPrints={historical ? state.physicalPrints.filter((record) => record.conversationId === viewedId) : state.physicalPrints}
          changes={state.changes.filter((change) => change.conversationId === viewedId)}
          work={state.work.filter((entry) => entry.conversationId === viewedId)}
          onWorkCancel={sendWorkCancel}
          restorePoints={historical ? [] : state.restorePoints}
          onRevert={(versionId) => client.send('shell_action', { action: 'revert_to_here', versionId })}
          onRetry={(messageId) => client.send('retry_message', { messageId, conversationId: viewedId })}
          onToolCancel={sendToolCancel}
          onSend={sendMessage}
          replyDisabled={unavailable || streaming || historical || state.projectChatBlocked}
          readOnly={historical || state.projectChatBlocked}
          onDiscussFailure={(text) => sendMessage(text, false)}
          onSetUpAgent={openSetup}
        />
      );
    if (setupScreen === 'chooser')
      return <SetupChooser onUseApiKey={() => setSetupScreen('apiKey')} onConnectTool={() => setSetupScreen('localTool')} onDismiss={closeSetup} />;
    if (setupScreen === 'localTool')
      return (
        <SetupLocalTool
          catalog={state.mcpCatalog}
          preview={state.mcpPreview}
          status={state.mcpStatus}
          onRefresh={() => client.send('mcp_catalog', {})}
          onPreview={(toolId) => client.send('mcp_preview', { toolId })}
          onConnect={(toolId) => client.send('mcp_connect', { toolId })}
          onReveal={(toolId) => client.send('reveal_path', { toolId })}
          onBack={() => setSetupScreen('chooser')}
          onDone={closeSetup}
        />
      );
    if (setupScreen === 'apiKey')
      return (
        <SetupApiKey
          setup={state.setup}
          onCheck={checkKey}
          onCancel={cancelCheck}
          onBack={() => {
            cancelCheck();
            setSetupScreen('chooser');
          }}
        />
      );
    return <AgentNotConfiguredPane onSetUp={openSetup} fileReports={fileReportNotes} />;
  };

  if (printerPanel) {
    const session = state.session;
    const printerAction = (action: string) => client.send('printer_action', { action });
    // No tool closes the panel for the model: the person decides when they
    // are done, with Back or by opening the printer's own settings.
    const back = () => {
      const started = state.messages.some((message) => message.role === 'user') ||
        state.attachments.some((attachment) => attachment.state === 'staged') || printerDraft.current.trim() !== '';
      if (started) setConfirmPrinterClose(true);
      else printerAction('close');
    };
    return (
      // The whole panel takes a photo, not only the composer: a picture of
      // the printer is dropped where the person is looking.
      <div
        className="app app--printer app--printer-setup"
        onDragOver={(event) => event.preventDefault()}
        onDrop={(event) => {
          const files = Array.from(event.dataTransfer.files ?? []);
          if (files.length === 0) return;
          event.preventDefault();
          attachFiles(files, 'drop');
        }}
      >
        {errorNotice}
        <div className="chat-content">
          <header className="chat-header printer-header">
            <button type="button" className="panel-link-button panel-back-link" onClick={back}>
              <span className="jp-icon jp-icon-chevron-left" aria-hidden="true" /> Back
            </button>
            <button type="button" className="panel-link-button" onClick={() => printerAction(session?.printerName ? 'open_printer_settings' : 'manual_setup')}>
              {session?.printerName ? 'Open printer settings' : 'Browse the full printer list'}
            </button>
          </header>
          {confirmPrinterClose && (
            <Dialog title="Close this conversation?" onClose={() => setConfirmPrinterClose(false)}>
              <p>This conversation will be closed. You can't continue it at a later point. Are you sure?</p>
              <div className="chat-dialog-buttons">
                <button type="button" onClick={() => setConfirmPrinterClose(false)}>Cancel</button>
                <button type="button" className="danger decisive" onClick={() => { setConfirmPrinterClose(false); printerAction('close'); }}>
                  Close conversation
                </button>
              </div>
            </Dialog>
          )}
          {notConfigured ? (
            body()
          ) : (
            <MessageList
              messages={state.messages}
              attachments={state.attachments}
              streamingMessageId={state.streamingMessageId}
              onSend={sendMessage}
              replyDisabled={unavailable || streaming}
              toolActivities={state.toolActivities.filter((activity) => activity.tool === 'settings_apply_patch' ||
                activity.actionId === session?.credentialRequest?.actionId)}
              renderActivity={(activity) => activity.actionId !== session?.credentialRequest?.actionId ? undefined : (
                <PrinterCredentialForm request={session.credentialRequest} onConnect={connectPrinter} />
              )}
              builds={[]}
              exportedCopies={[]}
              physicalPrints={[]}
              changes={[]}
              printerBlocks={session?.blocks ?? []}
              onUndoAdd={(blockId) => client.send('printer_action', { action: 'undo_add', blockId })}
              onInstallPlugin={() => client.send('printer_action', { action: 'install_network_plugin' })}
              onRetry={(messageId) => client.send('retry_message', { messageId })}
              onToolCancel={sendToolCancel}
            />
          )}
          {!notConfigured && (
            <Composer
              disabled={unavailable}
              disabledReason={unavailable ? 'The Agent is not available' : undefined}
              placeholder={session ? placeholder(session) : undefined}
              photoButton
              streaming={streaming}
              attachments={stagedAttachments}
              onDraftChange={(text) => { printerDraft.current = text; }}
              draftDebounceMs={0}
              onSend={(text) => { printerDraft.current = ''; sendMessage(text); }}
              onStop={() => {
                if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
              }}
              onAttachFiles={attachFiles}
              onPickFiles={pickFiles}
              onRemoveAttachment={removeAttachment}
            />
          )}
        </div>
      </div>
    );
  }

  if (embedded) {
    // No conversation header, chat list, composer, or external-tool banner --
    // just the setup sub-component itself, at whatever size its host gives it.
    return (
      <div className="app app--embedded">
        {errorNotice}
        <div className="chat-content">{body()}</div>
      </div>
    );
  }

  return (
    <div className={state.navigation.focused ? 'app app--focused-chat' : 'app'}>
      {errorNotice}
      {view === 'list' && !state.navigation.focused && chatList}
      <div className="chat-content" hidden={view === 'list'}>
      {notConfigured && state.conversations.length === 1 && view !== 'setup' && view !== 'setupDetails' && !state.navigation.focused ? (
        <>
          <AgentNotConfiguredHeader onCollapse={collapseAgentPane} />
          {setupCard}
        </>
      ) : view === 'setupDetails' ? (
        <SetupPageHeader onBack={() => setView('chat')} onCollapse={collapseAgentPane} />
      ) : state.navigation.focused ? (
        <header className="chat-header printer-header">
          <button type="button" className="panel-link-button panel-back-link" aria-label={state.navigation.returnLabel ?? 'Back to Prepare'}
            onClick={() => { if (view === 'setup') closeSetup(); else returnToWorkspace(); }}><span className="jp-icon jp-icon-chevron-left" aria-hidden="true" /> Back</button>
          {view !== 'setup' && <button type="button" className="panel-link-button"
            onClick={() => client.send('shell_action', { action: 'open_filament_settings' })}>Open filament settings</button>}
          <AgentPaneToggle onCollapse={collapseAgentPane} />
        </header>
      ) : (
        <>
          <ChatHeader key={`header-${state.context?.sessionId}-${viewedId}`} title={viewedChat?.title || 'New chat'} busy={busy || pendingAction}
            onBack={() => { if (view === 'setup') closeSetup(); else { client.send('state_request', {}); setView('list'); } }}
            onCreate={createChat}
            onRename={(title) => client.send('rename_conversation', { conversationId: viewedId, title })}
            onDelete={() => { client.send('delete_conversation', { conversationId: viewedId }); setView('list'); }}
            onCollapse={collapseAgentPane} />
          {setupCard}
        </>
      )}
      {!notConfigured && connected && (
        <ConnectedBanner
          provider={connected.provider}
          warning={connected.warning}
          onDismiss={() => setConnected(null)}
        />
      )}
      {body()}
      {/* An earlier chat is read-only: its composer is an empty, disabled
          shell under the notice, with no draft and no attachments. */}
      {view === 'chat' && historical && <Composer
        key={`composer-historical-${viewedId}`}
        disabled
        disabledReason=""
        attachable={false}
        streaming={false}
        attachments={[]}
        notice={<>{blockedAlert}{projectUpdates}</>}
        onSend={() => {}}
        onStop={() => {}}
        onAttachFiles={() => {}}
        onRemoveAttachment={() => {}}
      />}
      {!historical && state.navigation.focused && notConfigured && blockedAlert}
      {!historical && !(state.navigation.focused && notConfigured) && <div hidden={view !== 'chat'}><Composer
        key={`composer-${state.context?.sessionId}-${viewedId}`}
        disabled={unavailable || state.projectChatBlocked}
        disabledReason={state.projectChatBlocked ? 'Project restoration needs recovery.' : notConfigured ? 'ask, or steer this chat…' : unavailable ? 'The Agent is not available' : undefined}
        attachable={!state.projectChatBlocked}
        notice={blockedAlert || undefined}
        placeholder={state.navigation.focused ? 'Ask about this filament or request a change…' : undefined}
        streaming={streaming}
        initialText={state.draft}
        attachments={stagedAttachments}
        onSend={sendMessage}
        onStop={() => {
          if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
        }}
        onAttachFiles={attachFiles}
        onPickFiles={pickFiles}
        onRemoveAttachment={removeAttachment}
        models={state.modelCatalog}
        chatModel={state.chatModel}
        onChooseModel={(choice) => client.send('set_chat_model', { ...choice })}
        onDraftChange={(text) => client.send('draft_update', { text })}
        draftDebounceMs={draftDebounceMs}
      /></div>}
      {confirmChatRestore && historical && <Dialog title="Restore this chat's project setup?"
        onClose={() => setConfirmChatRestore(false)}>
        <p>Restore “{viewedChat?.title || 'this chat'}” from {state.chatResume.savedAt || 'its saved checkpoint'}? Its earlier model and settings will replace the working version, with the matching intent and plan. Your current version will remain in history.</p>
        <div className="chat-dialog-buttons">
          <button type="button" onClick={() => setConfirmChatRestore(false)}>Cancel</button>
          <button type="button" className="primary" disabled={busy} onClick={() => {
            setConfirmChatRestore(false);
            client.send('restore_conversation', {
              conversationId: viewedId, activeConversationId: state.activeConversationId, docRevision: state.docRevision,
            });
          }}>Restore and resume</button>
        </div>
      </Dialog>}
      </div>
    </div>
  );
}

content.content:
1	// Typed view of the jusprin-agent-bridge protocol. The canonical shared
2	// source is resources/jusprin/agent/protocol.json; the constants here are
3	// derived from it at build time so the page and the native host cannot
4	// silently disagree about the protocol name or version.
5	
6	import protocolJson from '@resources/jusprin/agent/protocol.json';
7	
8	export const PROTOCOL_NAME: string = protocolJson.name;
9	export const PROTOCOL_VERSION: number = protocolJson.version;
10	export const PAGE_CAPABILITIES: string[] = protocolJson.capabilities;
11	
12	export type PageMessageType =
13	  | 'hello'
14	  | 'state_request'
15	  | 'user_message'
16	  | 'stop_generation'
17	  | 'retry_message'
18	  | 'tool_cancel'
19	  | 'work_cancel'
20	  | 'create_conversation'
21	  | 'switch_conversation'
22	  | 'restore_conversation'
23	  | 'rename_conversation'
24	  | 'delete_conversation'
25	  | 'draft_update'
26	  | 'attach_file'
27	  | 'remove_attachment'
28	  | 'setup_check_key'
29	  | 'setup_cancel'
30	  | 'mcp_catalog'
31	  | 'mcp_preview'
32	  | 'mcp_connect'
33	  | 'reveal_path'
34	  | 'pick_attachment'
35	  | 'set_chat_model'
36	  | 'printer_action'
37	  | 'printer_instructions'
38	  | 'printer_opening'
39	  | 'filament_instructions'
40	  | 'shell_action'
41	  | 'project_instructions'
42	  | 'skills';
43	
44	export type HostMessageType =
45	  | 'hello_ack'
46	  | 'hello_reject'
47	  | 'state'
48	  | 'conversations_updated'
49	  | 'context'
50	  | 'appearance'
51	  | 'agent_status'
52	  | 'message_added'
53	  | 'assistant_started'
54	  | 'assistant_delta'
55	  | 'assistant_completed'
56	  | 'assistant_failed'
57	  | 'assistant_stopped'
58	  | 'tool_activity'
59	  | 'bridge_error'
60	  | 'attachment_updated'
61	  | 'setup_status'
62	  | 'mcp_catalog'
63	  | 'mcp_preview'
64	  | 'mcp_status'
65	  | 'change_added'
66	  | 'work_updated'
67	  | 'open_setup'
68	  | 'model_catalog'
69	  | 'chat_model'
70	  | 'printer_session';
71	
72	export interface Envelope<T = unknown> {
73	  protocol: string;
74	  version: number;
75	  id: string;
76	  type: string;
77	  correlationId?: string;
78	  sessionId?: string;
79	  revision?: number;
80	  payload: T;
81	}
82	
83	// 'note' is the host's own voice: a short factual line the native shell posts
84	// when it changes something the reader should see in the thread (a filament
85	// change, for example). It is never a turn -- no reply follows it, and the host never
86	// sends it to the model -- so it renders as a plain line, not a bubble.
87	export type MessageRole = 'user' | 'assistant' | 'note';
88	export type MessageStateName = 'complete' | 'streaming' | 'failed' | 'stopped';
89	export type AgentStatus = 'ready' | 'unavailable';
90	export type Appearance = 'light' | 'dark';
91	
92	export interface AgentErrorInfo {
93	  code: string;
94	  message: string;
95	  retryable: boolean;
96	}
97	
98	export interface WireMessage {
99	  id: string;
100	  role: MessageRole;
101	  state: MessageStateName;
102	  text: string;
103	  attempt: number;
104	  clientMessageId?: string;
105	  inReplyTo?: string;
106	  error?: AgentErrorInfo;
107	  attachments?: string[]; // sent attachment IDs, resolved against StatePayload.attachments
108	  swatch?: string; // notes: a colour, '#RRGGBB', that leads the line
109	  // Notes: what the app knows once a file the person brought in has loaded.
110	  // The model reads it; the page draws it only as a card, when the Agent
111	  // could not speak about it (fileReportCard).
112	  fileReport?: FileReport;
113	  fileReportCard?: boolean;
114	  // User messages sent from a print-issue bubble on the canvas: the issue,
115	  // its target and the freshness of the evidence, for the model. The page
116	  // draws the message's text and nothing from here.
117	  issueContext?: unknown;
118	}
119	
120	// Raw words shown or scheduled by Orca during opening, and the app's answer
121	// when there was a dialog. An empty answer belongs to a notification or error.
122	export interface OrcaMessage {
123	  source?: 'dialog' | 'notification' | 'error' | 'app';
124	  title: string;
125	  text: string;
126	  buttons: ('ok' | 'yes' | 'no' | 'cancel')[];
127	  answer: 'ok' | 'yes' | 'no' | 'cancel' | '';
128	  recognized?: false; // present only for a dialog the app did not know how to answer
129	}
130	
131	interface LoadSelectedSetup {
132	  printerPreset: string;
133	  filamentPreset: string;
134	  processPreset: string;
135	  printerOrigin: string;
136	  filamentOrigin: string;
137	  processOrigin: string;
138	  materialType?: string;
139	}
140	
141	export interface FileReport {
142	  startedBy: 'agent' | 'user';
143	  projectOpened: boolean;
144	  projectPath?: string;
145	  uiLanguage?: string;
146	  loads: { files: string[]; withSettings: boolean }[];
147	  // bedMm: the printable area's width and depth and the printable height.
148	  setupPrinters?: { name: string; model: string; nozzleMm: number; bedMm?: [number, number, number] }[];
149	  setupPrintersTruncated?: boolean;
150	  selectedPrinterBedMm?: [number, number, number];
151	  connectedPrinter?: string;
152	  messages: { items: OrcaMessage[]; truncated: boolean };
153	  loadFacts?: {
154	    settingsOutcome: 'applied' | 'geometry_only' | 'not_applied' | 'not_applicable';
155	    selectedSetupBefore: LoadSelectedSetup;
156	    selectedSetupAfter: LoadSelectedSetup;
157	    selectedSetupChange: Partial<Record<'printerPreset' | 'filamentPreset' | 'processPreset', { from: string; to: string }>>;
158	  };
159	  details?: Record<string, { value: string; provenance: 'project_file' }>;
160	  objects: { items: LoadedObject[]; truncated: boolean };
161	  // What each loaded 3MF states about itself.
162	  fileFacts?: {
163	    file: string;
164	    application?: string;
165	    madeFor?: { printerModel?: string; nozzleMm?: number };
166	    filaments?: { type: string; colour: string }[];
167	  }[];
168	  truncated: boolean;
169	}
170	
171	// An arrived object, with what the app checked about it.
172	interface LoadedObject {
173	  objectId: string;
174	  name: string;
175	  sizeMm: [number, number, number];
176	  placedOnBed?: boolean;
177	  fitsSelectedBed?: boolean;
178	  fitsSetupPrinters?: string[];
179	  mesh?: { triangles: number; shells: number; openEdges: number; repairedErrors: number; unitsSuspicion?: 'inches' | 'meters' };
180	  customized?: string[];
181	}
182	
183	// How a file entered the composer.
184	export type AttachmentSource = 'picker' | 'drop' | 'clipboard' | 'project';
185	
186	// What the composer's + menu asks the host's own file dialog for, when the
187	// host has the native_file_picker capability: one kind, filtered by the host
188	// to the extensions it files under that kind.
189	export type AttachmentPickKind = 'image' | 'model' | 'gcode' | 'pdf';
190	
191	// A chat's provider, model and thinking level (model_choice capability). An
192	// empty effort means the model's own default.
193	export interface ChatModelChoice {
194	  provider: string;
195	  model: string;
196	  effort: string;
197	}
198	
199	export interface ModelOptionInfo {
200	  id: string;
201	  label: string;
202	  // Levels the model accepts, lowest first; empty when it has none.
203	  efforts: string[];
204	  defaultEffort?: string;
205	}
206	
207	export interface ProviderModelsInfo {
208	  id: string;
209	  label: string;
210	  defaultModel: string;
211	  state: 'loading' | 'ready' | 'failed';
212	  models: ModelOptionInfo[];
213	}
214	
215	export interface ModelCatalogPayload {
216	  defaultProvider: string;
217	  providers: ProviderModelsInfo[];
218	}
219	
220	// The host's classification of an attachment. Model/project files go through
221	// Orca's native importer and reach the Agent as a native summary, never as
222	// decoded bytes; unknown/unsupported binaries are rejected visibly.
223	export type AttachmentKind =
224	  | 'text'
225	  | 'image'
226	  | 'svg'
227	  | 'pdf'
228	  | 'gcode'
229	  | 'model'
230	  | 'unsupported';
231	
232	// Lifecycle of one attachment. 'staged' is in the composer but not yet sent;
233	// 'sent' belongs to a durable user message; 'error' failed to decode/store.
234	export type AttachmentState = 'staged' | 'sent' | 'error';
235	
236	export interface AttachmentInfo {
237	  id: string;
238	  name: string; // original file name (display only)
239	  kind: AttachmentKind;
240	  mime: string;
241	  sizeBytes: number;
242	  source: AttachmentSource;
243	  state: AttachmentState;
244	  // Host-decoded preview, present where the kind supports it and the blob is
245	  // within the inline cap. Reconstructed from native state after a reload.
246	  previewText?: string; // text/gcode/svg source, truncated
247	  previewDataUrl?: string; // image thumbnails
248	  // A native, non-binary description of an imported model for Agent context.
249	  summary?: string;
250	  error?: { code: string; message: string };
251	}
252	
253	// Where a credential check has got to. 'verified' means the provider
254	// answered and the Agent is being connected; 'warning' is set when the key
255	// worked but could not be written to JusPrin's settings.
256	export type SetupPhase = 'idle' | 'checking' | 'verified' | 'error';
257	
258	export interface SetupStatusPayload {
259	  phase: SetupPhase;
260	  provider?: string;
261	  elapsedMs?: number;
262	  error?: AgentErrorInfo;
263	  warning?: string;
264	}
265	
266	export interface McpToolInfo {
267	  id: string;
268	  name: string;
269	  subtitle?: string;
270	  detected: boolean;
271	  cli: boolean;
272	  text: string;
273	  configPath?: string;
274	}
275	
276	export interface McpCatalogPayload {
277	  tools: McpToolInfo[];
278	  liveUrl?: string;
279	  helperPresent: boolean;
280	  startupError?: string;
281	}
282	
283	export interface McpPreviewPayload {
284	  toolId: string;
285	  path: string;
286	  // Absent when the file has no JusPrin entry yet. The host omits the field
287	  // rather than sending a serialised null, so "nothing there yet" stays
288	  // distinguishable from a real entry the user should read.
289	  previous?: string;
290	  next: string;
291	  root: string;
292	}
293	
294	export interface McpStatusPayload {
295	  phase: 'idle' | 'writing' | 'saved' | 'error';
296	  toolId?: string;
297	  backup?: string;
298	  diagnostic?: string;
299	  error?: AgentErrorInfo;
300	}
301	
302	// Time and material for one plate's current slice. Null whenever that plate
303	// holds no valid slice result: OrcaSlicer has no background slicing, so there
304	// is no honest estimate before Slice and the card omits the row rather than
305	// showing a zero. materialCost is null on its own whenever the filament
306	// profile carries no price, which is the default.
307	export interface SliceEstimateInfo {
308	  printTimeSeconds: number;
309	  materialGrams: number;
310	  materialCost: number | null;
311	  timeAvailable?: boolean;
312	  materialAvailable?: boolean;
313	}
314	
315	// One setting whose value in force differs from the preset it came from, as
316	// the setup page lists it.
317	export interface PresetDeltaInfo {
318	  key: string;
319	  label: string;
320	  preset: string;
321	  value: string;
322	  // Which preset the setting belongs to, and that preset's full name.
323	  presetType: 'process' | 'filament' | 'printer';
324	  presetName: string;
325	  // "0 → 8 mm": the change as the host's formatter writes it, from the
326	  // setting's own type, unit and choice labels. Absent when the formatter
327	  // has nothing to say; the page then shows the raw pair above.
328	  display?: string;
329	  // Where the setting sits in OrcaSlicer's settings tabs. Absent when
330	  // OrcaSlicer files the setting under no group.
331	  page?: string;
332	  group?: string;
333	}
334	
335	// What the estimate is worth right now. The number is kept in all three: a
336	// slice in flight or invalidated does not make the last honest figure
337	// worthless, and blanking it kills the comparison the reader is making.
338	export type EstimateStatus = 'current' | 'recomputing' | 'stale';
339	
340	// The settings in force for the printable objects on one plate, read from
341	// OrcaSlicer on the GUI thread. Every value is the raw serialized config value
342	// under its stable key; wording is the card's job. `coverage` says how far a
343	// single value can be trusted: exact for the whole plate, mixed across
344	// objects, local when a modifier, part, height range or paint overrides it
345	// somewhere, unavailable when nothing printable defines it.
346	export interface AppliedSetupInfo {
347	  version: number;
348	  plateId: string;
349	  printableObjects: number;
350	  spiralMode: boolean;
351	  variableLayerHeight: boolean;
352	  // Names of the printable objects, in the order `object` indexes them.
353	  objects: string[];
354	  localOverrides: {
355	    object?: number;
356	    target: string;
357	    kind: string;
358	    // Empty for a customization with no setting of its own: paint, a blocker.
359	    key: string;
360	    value: string;
361	    // The setting's name and its value as the host's formatter writes it.
362	    // Absent for a customization OrcaSlicer defines no setting for.
363	    label?: string;
364	    display?: string;
365	  }[];
366	}
367	
368	export interface SetupIdentityInfo {
369	  printer: string;
370	  nozzles: number[];
371	  plateType: string;
372	  filaments: { preset: string; material: string }[];
373	}
374	
375	export interface PrinterReviewInfo {
376	  observed?: { connection?: string; observedAt?: string };
377	  mismatches: { what: string; configured: string; observed: string; source: 'device' | 'user_confirmed' }[];
378	  confirmedFacts?: { fact: string; confirmedAt: string }[];
379	}
380	
381	export interface WorkspaceContext {
382	  sessionId: string;
383	  revision: number;
384	  projectName: string;
385	  projectDirty: boolean;
386	  // `process` is the preset the setting deltas are measured against, so it is
387	  // the name the setup card shows; `preset` is the machine and `filament` slot
388	  // 1's filament. Empty for a non-FFF printer, which has no process preset.
389	  printer: { preset: string; filament: string; process: string };
390	  plates: {
391	    id: string;
392	    name: string;
393	    active: boolean;
394	    sliced: boolean;
395	    estimate: SliceEstimateInfo | null;
396	    estimateStatus: EstimateStatus;
397	    // Which of the user's actions invalidated the slice, when it is known.
398	    // Empty otherwise: the card says nothing rather than attributing the loss
399	    // to something the reader did not do.
400	    invalidatedBy: string;
401	    // Why the plate's last slice did not succeed: OrcaSlicer refused it or the
402	    // run failed. Absent once the plate slices.
403	    sliceFailure?: {
404	      kind: 'refused' | 'failed';
405	      severity: 'blocker' | 'warning';
406	      message: string;
407	      setting?: string;
408	      objectId?: string;
409	    };
410	    objects: { id: string; name: string; instances: number; selected: boolean }[];
411	  }[];
412	  selection: { status: 'none' | 'objects' | 'unsupported'; objectIds: string[] };
413	  history: { canUndo: boolean; canRedo: boolean };
414	  presetDeltas: PresetDeltaInfo[];
415	  // Null when the host could not read them.
416	  appliedSetup: AppliedSetupInfo | null;
417	  setupIdentity: SetupIdentityInfo | null;
418	  printerReview: PrinterReviewInfo | null;
419	  // ISO 4217 code from the machine's regional settings, empty when the OS does
420	  // not say. OrcaSlicer itself has no currency concept, so this is the only
421	  // thing that says what a cost is denominated in.
422	  currency: string;
423	  // The card's chat's own records, which the host adds to the workspace for
424	  // the card: they are never saved with a checkpoint's summary.
425	  // The agent's restatement of what this chat asked the setup to be, in the
426	  // user's words. Empty until the agent records one.
427	  setupIntent: string;
428	  // How the agent means to print, in a few words: the headline of the plan
429	  // it pinned with setup_record. Empty until it pins one.
430	  planHeadline: string;
431	}
432	
433	// Lifecycle of one native tool action. Terminal states are 'succeeded',
434	// 'failed', and 'cancelled'; a stale action arrives as
435	// state 'failed' with error code 'stale_revision'.
436	export type ToolStateName =
437	  | 'running'
438	  | 'succeeded'
439	  | 'failed'
440	  | 'cancelled';
441	
442	export type ActionClassName = 'read_only' | 'mutation' | 'destructive';
443	
444	// Work the application ran outside the chat: a slice, an arrange, an export.
445	// Saved with the project at the place in the timeline where it started
446	// (`afterId`), and completed in place. `interrupted` is an entry that was
447	// still running when its project was closed.
448	export type WorkStateName = 'running' | 'done' | 'cancelled' | 'failed' | 'interrupted';
449	
450	export interface WorkInfo {
451	  seq: number;
452	  id: string;
453	  startedAt: string;
454	  endedAt: string;
455	  kind: string; // slice | job | export | upload | download
456	  title: string;
457	  state: WorkStateName;
458	  detail: string;
459	  conversationId: string;
460	  afterId: string; // the conversation item it follows; empty before the first
461	  cancellable: boolean;
462	  progress?: { current: number; total: number }; // only while running; total 0 = not known
463	}
464	
465	export interface ToolActivityInfo {
466	  actionId: string;
467	  correlationId: string; // assistant message or external adapter request
468	  source?: 'agent' | 'mcp'; // absent in older native builds: in-app Agent
469	  server: string;
470	  tool: string;
471	  title: string;
472	  arguments: Record<string, unknown>;
473	  actionClass: ActionClassName;
474	  sessionId: string;
475	  expectedRevision: number;
476	  state: ToolStateName;
477	  progress: { current: number; total: number };
478	  result?: Record<string, unknown>;
479	  error?: { code: string; message: string };
480	}
481	
482	export interface ConversationInfo {
483	  id: string;
484	  title: string;
485	  createdAt: string;
486	  updatedAt?: string;
487	  preview?: string;
488	}
489	
490	// One entry of the change log: an edit the workspace reported, stored raw.
491	// The page merges consecutive identical edits into one row for display.
492	//   step     a real undo step; label is OrcaSlicer's step name, maybe empty
493	//   undo     label is the step undone;  redo: the step redone
494	//   setting  label is the setting's name; from/to are its two values as a
495	//            person reads them ("Outer brim only", "8 mm"); preset is the
496	//            preset it was edited in
497	//   preset   a whole preset was switched; label is the new preset
498	//   restore  the model and settings were restored from an earlier saved version
499	export type ChangeKind = 'step' | 'undo' | 'redo' | 'setting' | 'preset' | 'restore';
500	
501	export interface ChangeInfo {
502	  seq: number;
503	  createdAt: string;
504	  kind: ChangeKind;
505	  actor: 'person' | 'agent';
506	  // An agent edit made by an external tool through the MCP server, not by the
507	  // in-app Agent. Absent from entries logged before the two were told apart.
508	  external?: boolean;
509	  label: string;
510	  location?: string;
511	  from?: string;
512	  to?: string;
513	  preset?: string;
514	  // Setting only: the config key, because labels are not unique. Absent from
515	  // entries logged before the card ordered its rows by them.
516	  key?: string;
517	  conversationId: string;
518	  afterId: string; // the message or tool activity it follows; '' before the first
519	}
520	
521	export interface RestorePointInfo {
522	  changeSeq: number;
523	  versionId: string;
524	}
525	
526	export interface SliceStatisticsInfo {
527	  printTimeSeconds: number;
528	  filamentMm: number;
529	  materialGrams: number;
530	  materialCost: number;
531	  layerCount: number;
532	}
533	
534	export interface BuildInfo {
535	  id: string;
536	  seq: number;
537	  createdAt: string;
538	  projectId: string;
539	  conversationId: string;
540	  afterMessageId: string;
541	  plateIndex: number;
542	  plateName: string;
543	  printer: string;
544	  material: string;
545	  manufacturingInputHash: string;
546	  outputHash: string;
547	  slicerVersion: string;
548	  configurationProvenance: string;
549	  sentAt?: string;
550	  deliveryConfirmedAt?: string;
551	  deliveryLocation?: string;
552	  statistics: SliceStatisticsInfo;
553	  warnings: string[];
554	  stale: boolean; // derived by the host from the current same-plate input hash
555	}
556	
557	export interface ExportedCopyInfo {
558	  id: string;
559	  seq: number;
560	  createdAt: string;
561	  buildId: string;
562	  conversationId: string;
563	  afterMessageId: string;
564	  destination: string;
565	  expectedOutputHash: string;
566	  observedOutputHash: string;
567	  verified: boolean; // derived by checksum comparison
568	  modified: boolean; // derived by checksum comparison
569	}
570	
571	export interface PhysicalPrintInfo {
572	  id: string;
573	  seq: number;
574	  startedAt: string;
575	  endedAt: string;
576	  outcome: 'completed' | 'failed' | 'cancelled';
577	  failure: string;
578	  buildId: string;
579	  projectId: string;
580	  conversationId: string;
581	  afterMessageId: string;
582	  plateIndex: number;
583	  plateName: string;
584	  printer: string;
585	  material: string;
586	  manufacturingInputHash: string;
587	  outputHash: string;
588	  gcodeHash: string;
589	  stoppedPercent?: number;
590	  statistics: SliceStatisticsInfo;
591	}
592	
593	// -- The printer panel ------------------------------------------------------
594	// One session of the temporary printer task chat: the picture cards the thread
595	// draws, and the facts the model's instructions state. Every word the panel
596	// shows is made on the page. Absent on every host that is showing the
597	// project's own conversation.
598	
599	export interface PrinterSpoolInfo {
600	  name: string;
601	  material: string;
602	  colour?: string; // "#RRGGBB"
603	}
604	
605	export interface PrinterCardInfo {
606	  catalogId: string;
607	  name: string; // brand and model
608	  // The same name in its two parts, so the card can set the brand above the
609	  // model. Optional: the card shows `name` alone until the app sends both.
610	  brand?: string;
611	  model?: string;
612	  buildVolume: string; // "180 × 180 × 180 mm"
613	  picture: string; // data URL, empty when the profile ships no picture
614	}
615	
616	export interface NetworkPrinterInfo {
617	  name: string;
618	  serial: string;
619	  online: boolean;
620	  // What kind of printer it is ("Bambu A1"). Optional: left out of the row
621	  // until the app reports it.
622	  model?: string;
623	}
624	
625	// A card in the thread, anchored after the message it belongs to, in the same
626	// way tool activity and history entries are. Two have something to tap: Undo
627	// on the 'added' receipt, and Install on the 'plugin' notice.
628	export interface PrinterBlock {
629	  id: string;
630	  seq: number;
631	  afterMessageId: string;
632	  // 'plugin': Bambu's network plug-in is missing, so a Bambu Lab printer
633	  // cannot be reached.
634	  kind: 'tip' | 'network' | 'printers' | 'added' | 'plugin';
635	  printers?: PrinterCardInfo[] | NetworkPrinterInfo[];
636	  // 'added': the printer printer_add just saved, as it was saved.
637	  printer?: AddedPrinterInfo;
638	  // 'added': Undo removed it again.
639	  removed?: boolean;
640	  // 'plugin': the plug-in has been installed since.
641	  installed?: boolean;
642	}
643	
644	export interface AddedPrinterInfo {
645	  name: string;
646	  nozzle: number; // mm
647	  // What kind of printer was saved ("Bambu A1"). Optional: the receipt shows
648	  // the nozzle alone until the app reports it.
649	  model?: string;
650	}
651	
652	// The filament chat's facts, which its instructions state
653	// (filamentInstructions.ts): one filament preset, by name.
654	export interface FilamentSessionPayload {
655	  kind: 'filament';
656	  slot: number; // 1-based, as the person reads it
657	  preset: string;
658	  shown: string; // what the header calls it
659	  material: string;
660	  stock: boolean; // the settings OrcaSlicer comes with, saved only as a copy
661	  copyName?: string; // the copy a change to a stock filament is saved as
662	}
663	
664	export interface PrinterSessionPayload {
665	  mode: 'add' | 'change' | 'connect';
666	  // The printer the conversation is about; empty until one is added.
667	  printerName: string;
668	  blocks: PrinterBlock[];
669	  // The facts the model's instructions state (printerInstructions.ts).
670	  context: PrinterContext;
671	  // A printer credential requested by a completed tool call. The page sends
672	  // the secret straight back to the printer session, never through chat.
673	  credentialRequest?: PrinterCredentialRequest;
674	}
675	
676	export interface PrinterCredentialRequest {
677	  actionId: string;
678	  target: string;
679	  provider: 'bambu' | 'host';
680	}
681	
682	export interface PrinterContext {
683	  // Add: every printer the panel can set up, as [catalogId, brand and model,
684	  // build volume], and what is on the network now.
685	  printers?: [string, string, string][];
686	  network?: { name: string; serial: string }[];
687	  // The printer the conversation is about, as it is now.
688	  printer?: {
689	    name: string;
690	    model: string;
691	    nozzle: number;
692	    nozzles: number[];
693	    spools: PrinterSpoolInfo[];
694	    connected: boolean;
695	    provider: 'bambu' | 'host';
696	    // Bambu's network plug-in is missing, so nothing can reach it yet.
697	    needsNetworkPlugin?: boolean;
698	    // One of OrcaSlicer's own printer profiles, selected in the project,
699	    // rather than a printer the person added, and the name a copy of it is
700	    // saved under.
701	    stock?: boolean;
702	    copyName?: string;
703	  };
704	}
705	
706	export interface StatePayload {
707	  conversationBusy?: boolean;
708	  chatModel?: ChatModelChoice; // the active chat's, from hosts with model_choice
709	  agent: { status: AgentStatus };
710	  appearance: Appearance;
711	  conversations: ConversationInfo[];
712	  activeConversationId: string;
713	  viewedConversationId?: string;
714	  docRevision?: number;
715	  projectChatBlocked?: boolean;
716	  chatResume?: {
717	    status: 'active' | 'changed' | 'unchanged' | 'unavailable';
718	    savedAt?: string;
719	    versionId?: string;
720	    summary?: WorkspaceContext;
721	  };
722	  conversation: WireMessage[]; // messages of the viewed conversation
723	  streamingMessageId: string | null;
724	  toolActivities: ToolActivityInfo[];
725	  builds: BuildInfo[];
726	  exportedCopies: ExportedCopyInfo[];
727	  physicalPrints: PhysicalPrintInfo[];
728	  changes?: ChangeInfo[]; // absent from hosts without the change_log capability
729	  work?: WorkInfo[]; // absent from hosts without the work_log capability
730	  restorePoints?: RestorePointInfo[]; // committed model versions with an exact change boundary
731	  draft: string;
732	  attachments?: AttachmentInfo[]; // staged (composer) and sent (history) attachments
733	  context: WorkspaceContext;
734	  session?: PrinterSessionPayload | FilamentSessionPayload; // only in the printer and filament chats
735	  navigation?: { focused: boolean; returnLabel?: string }; // shell-owned full-screen project chat
736	}
737	
738	export function isEnvelope(value: unknown): value is Envelope {
739	  if (typeof value !== 'object' || value === null) return false;
740	  const env = value as Record<string, unknown>;
741	  return (
742	    env.protocol === PROTOCOL_NAME &&
743	    typeof env.version === 'number' &&
744	    typeof env.id === 'string' &&
745	    typeof env.type === 'string'
746	  );
747	}
748

file.content:
// Typed view of the jusprin-agent-bridge protocol. The canonical shared
// source is resources/jusprin/agent/protocol.json; the constants here are
// derived from it at build time so the page and the native host cannot
// silently disagree about the protocol name or version.

import protocolJson from '@resources/jusprin/agent/protocol.json';

export const PROTOCOL_NAME: string = protocolJson.name;
export const PROTOCOL_VERSION: number = protocolJson.version;
export const PAGE_CAPABILITIES: string[] = protocolJson.capabilities;

export type PageMessageType =
  | 'hello'
  | 'state_request'
  | 'user_message'
  | 'stop_generation'
  | 'retry_message'
  | 'tool_cancel'
  | 'work_cancel'
  | 'create_conversation'
  | 'switch_conversation'
  | 'restore_conversation'
  | 'rename_conversation'
  | 'delete_conversation'
  | 'draft_update'
  | 'attach_file'
  | 'remove_attachment'
  | 'setup_check_key'
  | 'setup_cancel'
  | 'mcp_catalog'
  | 'mcp_preview'
  | 'mcp_connect'
  | 'reveal_path'
  | 'pick_attachment'
  | 'set_chat_model'
  | 'printer_action'
  | 'printer_instructions'
  | 'printer_opening'
  | 'filament_instructions'
  | 'shell_action'
  | 'project_instructions'
  | 'skills';

export type HostMessageType =
  | 'hello_ack'
  | 'hello_reject'
  | 'state'
  | 'conversations_updated'
  | 'context'
  | 'appearance'
  | 'agent_status'
  | 'message_added'
  | 'assistant_started'
  | 'assistant_delta'
  | 'assistant_completed'
  | 'assistant_failed'
  | 'assistant_stopped'
  | 'tool_activity'
  | 'bridge_error'
  | 'attachment_updated'
  | 'setup_status'
  | 'mcp_catalog'
  | 'mcp_preview'
  | 'mcp_status'
  | 'change_added'
  | 'work_updated'
  | 'open_setup'
  | 'model_catalog'
  | 'chat_model'
  | 'printer_session';

export interface Envelope<T = unknown> {
  protocol: string;
  version: number;
  id: string;
  type: string;
  correlationId?: string;
  sessionId?: string;
  revision?: number;
  payload: T;
}

// 'note' is the host's own voice: a short factual line the native shell posts
// when it changes something the reader should see in the thread (a filament
// change, for example). It is never a turn -- no reply follows it, and the host never
// sends it to the model -- so it renders as a plain line, not a bubble.
export type MessageRole = 'user' | 'assistant' | 'note';
export type MessageStateName = 'complete' | 'streaming' | 'failed' | 'stopped';
export type AgentStatus = 'ready' | 'unavailable';
export type Appearance = 'light' | 'dark';

export interface AgentErrorInfo {
  code: string;
  message: string;
  retryable: boolean;
}

export interface WireMessage {
  id: string;
  role: MessageRole;
  state: MessageStateName;
  text: string;
  attempt: number;
  clientMessageId?: string;
  inReplyTo?: string;
  error?: AgentErrorInfo;
  attachments?: string[]; // sent attachment IDs, resolved against StatePayload.attachments
  swatch?: string; // notes: a colour, '#RRGGBB', that leads the line
  // Notes: what the app knows once a file the person brought in has loaded.
  // The model reads it; the page draws it only as a card, when the Agent
  // could not speak about it (fileReportCard).
  fileReport?: FileReport;
  fileReportCard?: boolean;
  // User messages sent from a print-issue bubble on the canvas: the issue,
  // its target and the freshness of the evidence, for the model. The page
  // draws the message's text and nothing from here.
  issueContext?: unknown;
}

// Raw words shown or scheduled by Orca during opening, and the app's answer
// when there was a dialog. An empty answer belongs to a notification or error.
export interface OrcaMessage {
  source?: 'dialog' | 'notification' | 'error' | 'app';
  title: string;
  text: string;
  buttons: ('ok' | 'yes' | 'no' | 'cancel')[];
  answer: 'ok' | 'yes' | 'no' | 'cancel' | '';
  recognized?: false; // present only for a dialog the app did not know how to answer
}

interface LoadSelectedSetup {
  printerPreset: string;
  filamentPreset: string;
  processPreset: string;
  printerOrigin: string;
  filamentOrigin: string;
  processOrigin: string;
  materialType?: string;
}

export interface FileReport {
  startedBy: 'agent' | 'user';
  projectOpened: boolean;
  projectPath?: string;
  uiLanguage?: string;
  loads: { files: string[]; withSettings: boolean }[];
  // bedMm: the printable area's width and depth and the printable height.
  setupPrinters?: { name: string; model: string; nozzleMm: number; bedMm?: [number, number, number] }[];
  setupPrintersTruncated?: boolean;
  selectedPrinterBedMm?: [number, number, number];
  connectedPrinter?: string;
  messages: { items: OrcaMessage[]; truncated: boolean };
  loadFacts?: {
    settingsOutcome: 'applied' | 'geometry_only' | 'not_applied' | 'not_applicable';
    selectedSetupBefore: LoadSelectedSetup;
    selectedSetupAfter: LoadSelectedSetup;
    selectedSetupChange: Partial<Record<'printerPreset' | 'filamentPreset' | 'processPreset', { from: string; to: string }>>;
  };
  details?: Record<string, { value: string; provenance: 'project_file' }>;
  objects: { items: LoadedObject[]; truncated: boolean };
  // What each loaded 3MF states about itself.
  fileFacts?: {
    file: string;
    application?: string;
    madeFor?: { printerModel?: string; nozzleMm?: number };
    filaments?: { type: string; colour: string }[];
  }[];
  truncated: boolean;
}

// An arrived object, with what the app checked about it.
interface LoadedObject {
  objectId: string;
  name: string;
  sizeMm: [number, number, number];
  placedOnBed?: boolean;
  fitsSelectedBed?: boolean;
  fitsSetupPrinters?: string[];
  mesh?: { triangles: number; shells: number; openEdges: number; repairedErrors: number; unitsSuspicion?: 'inches' | 'meters' };
  customized?: string[];
}

// How a file entered the composer.
export type AttachmentSource = 'picker' | 'drop' | 'clipboard' | 'project';

// What the composer's + menu asks the host's own file dialog for, when the
// host has the native_file_picker capability: one kind, filtered by the host
// to the extensions it files under that kind.
export type AttachmentPickKind = 'image' | 'model' | 'gcode' | 'pdf';

// A chat's provider, model and thinking level (model_choice capability). An
// empty effort means the model's own default.
export interface ChatModelChoice {
  provider: string;
  model: string;
  effort: string;
}

export interface ModelOptionInfo {
  id: string;
  label: string;
  // Levels the model accepts, lowest first; empty when it has none.
  efforts: string[];
  defaultEffort?: string;
}

export interface ProviderModelsInfo {
  id: string;
  label: string;
  defaultModel: string;
  state: 'loading' | 'ready' | 'failed';
  models: ModelOptionInfo[];
}

export interface ModelCatalogPayload {
  defaultProvider: string;
  providers: ProviderModelsInfo[];
}

// The host's classification of an attachment. Model/project files go through
// Orca's native importer and reach the Agent as a native summary, never as
// decoded bytes; unknown/unsupported binaries are rejected visibly.
export type AttachmentKind =
  | 'text'
  | 'image'
  | 'svg'
  | 'pdf'
  | 'gcode'
  | 'model'
  | 'unsupported';

// Lifecycle of one attachment. 'staged' is in the composer but not yet sent;
// 'sent' belongs to a durable user message; 'error' failed to decode/store.
export type AttachmentState = 'staged' | 'sent' | 'error';

export interface AttachmentInfo {
  id: string;
  name: string; // original file name (display only)
  kind: AttachmentKind;
  mime: string;
  sizeBytes: number;
  source: AttachmentSource;
  state: AttachmentState;
  // Host-decoded preview, present where the kind supports it and the blob is
  // within the inline cap. Reconstructed from native state after a reload.
  previewText?: string; // text/gcode/svg source, truncated
  previewDataUrl?: string; // image thumbnails
  // A native, non-binary description of an imported model for Agent context.
  summary?: string;
  error?: { code: string; message: string };
}

// Where a credential check has got to. 'verified' means the provider
// answered and the Agent is being connected; 'warning' is set when the key
// worked but could not be written to JusPrin's settings.
export type SetupPhase = 'idle' | 'checking' | 'verified' | 'error';

export interface SetupStatusPayload {
  phase: SetupPhase;
  provider?: string;
  elapsedMs?: number;
  error?: AgentErrorInfo;
  warning?: string;
}

export interface McpToolInfo {
  id: string;
  name: string;
  subtitle?: string;
  detected: boolean;
  cli: boolean;
  text: string;
  configPath?: string;
}

export interface McpCatalogPayload {
  tools: McpToolInfo[];
  liveUrl?: string;
  helperPresent: boolean;
  startupError?: string;
}

export interface McpPreviewPayload {
  toolId: string;
  path: string;
  // Absent when the file has no JusPrin entry yet. The host omits the field
  // rather than sending a serialised null, so "nothing there yet" stays
  // distinguishable from a real entry the user should read.
  previous?: string;
  next: string;
  root: string;
}

export interface McpStatusPayload {
  phase: 'idle' | 'writing' | 'saved' | 'error';
  toolId?: string;
  backup?: string;
  diagnostic?: string;
  error?: AgentErrorInfo;
}

// Time and material for one plate's current slice. Null whenever that plate
// holds no valid slice result: OrcaSlicer has no background slicing, so there
// is no honest estimate before Slice and the card omits the row rather than
// showing a zero. materialCost is null on its own whenever the filament
// profile carries no price, which is the default.
export interface SliceEstimateInfo {
  printTimeSeconds: number;
  materialGrams: number;
  materialCost: number | null;
  timeAvailable?: boolean;
  materialAvailable?: boolean;
}

// One setting whose value in force differs from the preset it came from, as
// the setup page lists it.
export interface PresetDeltaInfo {
  key: string;
  label: string;
  preset: string;
  value: string;
  // Which preset the setting belongs to, and that preset's full name.
  presetType: 'process' | 'filament' | 'printer';
  presetName: string;
  // "0 → 8 mm": the change as the host's formatter writes it, from the
  // setting's own type, unit and choice labels. Absent when the formatter
  // has nothing to say; the page then shows the raw pair above.
  display?: string;
  // Where the setting sits in OrcaSlicer's settings tabs. Absent when
  // OrcaSlicer files the setting under no group.
  page?: string;
  group?: string;
}

// What the estimate is worth right now. The number is kept in all three: a
// slice in flight or invalidated does not make the last honest figure
// worthless, and blanking it kills the comparison the reader is making.
export type EstimateStatus = 'current' | 'recomputing' | 'stale';

// The settings in force for the printable objects on one plate, read from
// OrcaSlicer on the GUI thread. Every value is the raw serialized config value
// under its stable key; wording is the card's job. `coverage` says how far a
// single value can be trusted: exact for the whole plate, mixed across
// objects, local when a modifier, part, height range or paint overrides it
// somewhere, unavailable when nothing printable defines it.
export interface AppliedSetupInfo {
  version: number;
  plateId: string;
  printableObjects: number;
  spiralMode: boolean;
  variableLayerHeight: boolean;
  // Names of the printable objects, in the order `object` indexes them.
  objects: string[];
  localOverrides: {
    object?: number;
    target: string;
    kind: string;
    // Empty for a customization with no setting of its own: paint, a blocker.
    key: string;
    value: string;
    // The setting's name and its value as the host's formatter writes it.
    // Absent for a customization OrcaSlicer defines no setting for.
    label?: string;
    display?: string;
  }[];
}

export interface SetupIdentityInfo {
  printer: string;
  nozzles: number[];
  plateType: string;
  filaments: { preset: string; material: string }[];
}

export interface PrinterReviewInfo {
  observed?: { connection?: string; observedAt?: string };
  mismatches: { what: string; configured: string; observed: string; source: 'device' | 'user_confirmed' }[];
  confirmedFacts?: { fact: string; confirmedAt: string }[];
}

export interface WorkspaceContext {
  sessionId: string;
  revision: number;
  projectName: string;
  projectDirty: boolean;
  // `process` is the preset the setting deltas are measured against, so it is
  // the name the setup card shows; `preset` is the machine and `filament` slot
  // 1's filament. Empty for a non-FFF printer, which has no process preset.
  printer: { preset: string; filament: string; process: string };
  plates: {
    id: string;
    name: string;
    active: boolean;
    sliced: boolean;
    estimate: SliceEstimateInfo | null;
    estimateStatus: EstimateStatus;
    // Which of the user's actions invalidated the slice, when it is known.
    // Empty otherwise: the card says nothing rather than attributing the loss
    // to something the reader did not do.
    invalidatedBy: string;
    // Why the plate's last slice did not succeed: OrcaSlicer refused it or the
    // run failed. Absent once the plate slices.
    sliceFailure?: {
      kind: 'refused' | 'failed';
      severity: 'blocker' | 'warning';
      message: string;
      setting?: string;
      objectId?: string;
    };
    objects: { id: string; name: string; instances: number; selected: boolean }[];
  }[];
  selection: { status: 'none' | 'objects' | 'unsupported'; objectIds: string[] };
  history: { canUndo: boolean; canRedo: boolean };
  presetDeltas: PresetDeltaInfo[];
  // Null when the host could not read them.
  appliedSetup: AppliedSetupInfo | null;
  setupIdentity: SetupIdentityInfo | null;
  printerReview: PrinterReviewInfo | null;
  // ISO 4217 code from the machine's regional settings, empty when the OS does
  // not say. OrcaSlicer itself has no currency concept, so this is the only
  // thing that says what a cost is denominated in.
  currency: string;
  // The card's chat's own records, which the host adds to the workspace for
  // the card: they are never saved with a checkpoint's summary.
  // The agent's restatement of what this chat asked the setup to be, in the
  // user's words. Empty until the agent records one.
  setupIntent: string;
  // How the agent means to print, in a few words: the headline of the plan
  // it pinned with setup_record. Empty until it pins one.
  planHeadline: string;
}

// Lifecycle of one native tool action. Terminal states are 'succeeded',
// 'failed', and 'cancelled'; a stale action arrives as
// state 'failed' with error code 'stale_revision'.
export type ToolStateName =
  | 'running'
  | 'succeeded'
  | 'failed'
  | 'cancelled';

export type ActionClassName = 'read_only' | 'mutation' | 'destructive';

// Work the application ran outside the chat: a slice, an arrange, an export.
// Saved with the project at the place in the timeline where it started
// (`afterId`), and completed in place. `interrupted` is an entry that was
// still running when its project was closed.
export type WorkStateName = 'running' | 'done' | 'cancelled' | 'failed' | 'interrupted';

export interface WorkInfo {
  seq: number;
  id: string;
  startedAt: string;
  endedAt: string;
  kind: string; // slice | job | export | upload | download
  title: string;
  state: WorkStateName;
  detail: string;
  conversationId: string;
  afterId: string; // the conversation item it follows; empty before the first
  cancellable: boolean;
  progress?: { current: number; total: number }; // only while running; total 0 = not known
}

export interface ToolActivityInfo {
  actionId: string;
  correlationId: string; // assistant message or external adapter request
  source?: 'agent' | 'mcp'; // absent in older native builds: in-app Agent
  server: string;
  tool: string;
  title: string;
  arguments: Record<string, unknown>;
  actionClass: ActionClassName;
  sessionId: string;
  expectedRevision: number;
  state: ToolStateName;
  progress: { current: number; total: number };
  result?: Record<string, unknown>;
  error?: { code: string; message: string };
}

export interface ConversationInfo {
  id: string;
  title: string;
  createdAt: string;
  updatedAt?: string;
  preview?: string;
}

// One entry of the change log: an edit the workspace reported, stored raw.
// The page merges consecutive identical edits into one row for display.
//   step     a real undo step; label is OrcaSlicer's step name, maybe empty
//   undo     label is the step undone;  redo: the step redone
//   setting  label is the setting's name; from/to are its two values as a
//            person reads them ("Outer brim only", "8 mm"); preset is the
//            preset it was edited in
//   preset   a whole preset was switched; label is the new preset
//   restore  the model and settings were restored from an earlier saved version
export type ChangeKind = 'step' | 'undo' | 'redo' | 'setting' | 'preset' | 'restore';

export interface ChangeInfo {
  seq: number;
  createdAt: string;
  kind: ChangeKind;
  actor: 'person' | 'agent';
  // An agent edit made by an external tool through the MCP server, not by the
  // in-app Agent. Absent from entries logged before the two were told apart.
  external?: boolean;
  label: string;
  location?: string;
  from?: string;
  to?: string;
  preset?: string;
  // Setting only: the config key, because labels are not unique. Absent from
  // entries logged before the card ordered its rows by them.
  key?: string;
  conversationId: string;
  afterId: string; // the message or tool activity it follows; '' before the first
}

export interface RestorePointInfo {
  changeSeq: number;
  versionId: string;
}

export interface SliceStatisticsInfo {
  printTimeSeconds: number;
  filamentMm: number;
  materialGrams: number;
  materialCost: number;
  layerCount: number;
}

export interface BuildInfo {
  id: string;
  seq: number;
  createdAt: string;
  projectId: string;
  conversationId: string;
  afterMessageId: string;
  plateIndex: number;
  plateName: string;
  printer: string;
  material: string;
  manufacturingInputHash: string;
  outputHash: string;
  slicerVersion: string;
  configurationProvenance: string;
  sentAt?: string;
  deliveryConfirmedAt?: string;
  deliveryLocation?: string;
  statistics: SliceStatisticsInfo;
  warnings: string[];
  stale: boolean; // derived by the host from the current same-plate input hash
}

export interface ExportedCopyInfo {
  id: string;
  seq: number;
  createdAt: string;
  buildId: string;
  conversationId: string;
  afterMessageId: string;
  destination: string;
  expectedOutputHash: string;
  observedOutputHash: string;
  verified: boolean; // derived by checksum comparison
  modified: boolean; // derived by checksum comparison
}

export interface PhysicalPrintInfo {
  id: string;
  seq: number;
  startedAt: string;
  endedAt: string;
  outcome: 'completed' | 'failed' | 'cancelled';
  failure: string;
  buildId: string;
  projectId: string;
  conversationId: string;
  afterMessageId: string;
  plateIndex: number;
  plateName: string;
  printer: string;
  material: string;
  manufacturingInputHash: string;
  outputHash: string;
  gcodeHash: string;
  stoppedPercent?: number;
  statistics: SliceStatisticsInfo;
}

// -- The printer panel ------------------------------------------------------
// One session of the temporary printer task chat: the picture cards the thread
// draws, and the facts the model's instructions state. Every word the panel
// shows is made on the page. Absent on every host that is showing the
// project's own conversation.

export interface PrinterSpoolInfo {
  name: string;
  material: string;
  colour?: string; // "#RRGGBB"
}

export interface PrinterCardInfo {
  catalogId: string;
  name: string; // brand and model
  // The same name in its two parts, so the card can set the brand above the
  // model. Optional: the card shows `name` alone until the app sends both.
  brand?: string;
  model?: string;
  buildVolume: string; // "180 × 180 × 180 mm"
  picture: string; // data URL, empty when the profile ships no picture
}

export interface NetworkPrinterInfo {
  name: string;
  serial: string;
  online: boolean;
  // What kind of printer it is ("Bambu A1"). Optional: left out of the row
  // until the app reports it.
  model?: string;
}

// A card in the thread, anchored after the message it belongs to, in the same
// way tool activity and history entries are. Two have something to tap: Undo
// on the 'added' receipt, and Install on the 'plugin' notice.
export interface PrinterBlock {
  id: string;
  seq: number;
  afterMessageId: string;
  // 'plugin': Bambu's network plug-in is missing, so a Bambu Lab printer
  // cannot be reached.
  kind: 'tip' | 'network' | 'printers' | 'added' | 'plugin';
  printers?: PrinterCardInfo[] | NetworkPrinterInfo[];
  // 'added': the printer printer_add just saved, as it was saved.
  printer?: AddedPrinterInfo;
  // 'added': Undo removed it again.
  removed?: boolean;
  // 'plugin': the plug-in has been installed since.
  installed?: boolean;
}

export interface AddedPrinterInfo {
  name: string;
  nozzle: number; // mm
  // What kind of printer was saved ("Bambu A1"). Optional: the receipt shows
  // the nozzle alone until the app reports it.
  model?: string;
}

// The filament chat's facts, which its instructions state
// (filamentInstructions.ts): one filament preset, by name.
export interface FilamentSessionPayload {
  kind: 'filament';
  slot: number; // 1-based, as the person reads it
  preset: string;
  shown: string; // what the header calls it
  material: string;
  stock: boolean; // the settings OrcaSlicer comes with, saved only as a copy
  copyName?: string; // the copy a change to a stock filament is saved as
}

export interface PrinterSessionPayload {
  mode: 'add' | 'change' | 'connect';
  // The printer the conversation is about; empty until one is added.
  printerName: string;
  blocks: PrinterBlock[];
  // The facts the model's instructions state (printerInstructions.ts).
  context: PrinterContext;
  // A printer credential requested by a completed tool call. The page sends
  // the secret straight back to the printer session, never through chat.
  credentialRequest?: PrinterCredentialRequest;
}

export interface PrinterCredentialRequest {
  actionId: string;
  target: string;
  provider: 'bambu' | 'host';
}

export interface PrinterContext {
  // Add: every printer the panel can set up, as [catalogId, brand and model,
  // build volume], and what is on the network now.
  printers?: [string, string, string][];
  network?: { name: string; serial: string }[];
  // The printer the conversation is about, as it is now.
  printer?: {
    name: string;
    model: string;
    nozzle: number;
    nozzles: number[];
    spools: PrinterSpoolInfo[];
    connected: boolean;
    provider: 'bambu' | 'host';
    // Bambu's network plug-in is missing, so nothing can reach it yet.
    needsNetworkPlugin?: boolean;
    // One of OrcaSlicer's own printer profiles, selected in the project,
    // rather than a printer the person added, and the name a copy of it is
    // saved under.
    stock?: boolean;
    copyName?: string;
  };
}

export interface StatePayload {
  conversationBusy?: boolean;
  chatModel?: ChatModelChoice; // the active chat's, from hosts with model_choice
  agent: { status: AgentStatus };
  appearance: Appearance;
  conversations: ConversationInfo[];
  activeConversationId: string;
  viewedConversationId?: string;
  docRevision?: number;
  projectChatBlocked?: boolean;
  chatResume?: {
    status: 'active' | 'changed' | 'unchanged' | 'unavailable';
    savedAt?: string;
    versionId?: string;
    summary?: WorkspaceContext;
  };
  conversation: WireMessage[]; // messages of the viewed conversation
  streamingMessageId: string | null;
  toolActivities: ToolActivityInfo[];
  builds: BuildInfo[];
  exportedCopies: ExportedCopyInfo[];
  physicalPrints: PhysicalPrintInfo[];
  changes?: ChangeInfo[]; // absent from hosts without the change_log capability
  work?: WorkInfo[]; // absent from hosts without the work_log capability
  restorePoints?: RestorePointInfo[]; // committed model versions with an exact change boundary
  draft: string;
  attachments?: AttachmentInfo[]; // staged (composer) and sent (history) attachments
  context: WorkspaceContext;
  session?: PrinterSessionPayload | FilamentSessionPayload; // only in the printer and filament chats
  navigation?: { focused: boolean; returnLabel?: string }; // shell-owned full-screen project chat
}

export function isEnvelope(value: unknown): value is Envelope {
  if (typeof value !== 'object' || value === null) return false;
  const env = value as Record<string, unknown>;
  return (
    env.protocol === PROTOCOL_NAME &&
    typeof env.version === 'number' &&
    typeof env.id === 'string' &&
    typeof env.type === 'string'
  );
}

