${productionCss()}
.dark { ${dark} }
html, body { height: auto; }
body { margin:0; padding:16px; background:var(--surface-subtle); color:var(--text-primary); font:var(--font-body); }
h1 { font:var(--font-section); margin:0 0 12px; }
