      .filter((id) => !['A1', 'A2', 'B'].includes(id)).sort());
  });

  it.each(Object.keys(expected))('%s', (id) => {
    const { root } = visual(id);
    for (const text of expected[id]) expect(root).toHaveTextContent(text);
