.all-settings-header {
  justify-content: space-between;
}

/* The scrolling body, in place of the thread. */
.all-settings {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 16px 16px;
  overflow-y: auto;
  background: var(--surface-canvas);
}

.all-settings-scope,
