  text-align: left;
  cursor: pointer;
}

.jp-select .composer-picker-text,
.jp-select > span:first-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.jp-select .jp-icon {
  flex: 0 0 auto;
  width: var(--select-chevron-size);
  height: var(--select-chevron-size);
  color: var(--text-secondary);
}

.jp-select:hover:enabled {
  box-shadow: inset 0 0 0 1px var(--border-strong);
}

.jp-select[aria-expanded='true'],
.jp-select:focus-visible {
