.all-settings-own {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font: var(--font-body-small);
  color: var(--text-primary);
}

.all-settings-groups {
  display: flex;
  flex-direction: column;
}

.all-settings-group {
  border-bottom: 1px solid var(--border-subtle);
}

/* A group's header is a 32 DIP row: the chevron, the name, and on the right
