.all-settings-group-header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 32px;
  padding: 0;
  border: 0;
  background: none;
  text-align: left;
  color: var(--text-primary);
  cursor: pointer;
}

.all-settings-group-header--empty {
  cursor: default;
}

.all-settings-group-header .jp-icon {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
  color: var(--text-secondary);
}

.all-settings-group-name {
  flex: 0 0 auto;
  font: var(--font-body-small-bold);
  white-space: nowrap;
}

.all-settings-group-summary {
  flex: 1 1 auto;
  min-width: 0;
  font: var(--font-label);
  color: var(--text-secondary);
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The rows sit under the name, past the chevron (icon 16 + gap 8). */
.all-settings-group-rows {
  display: flex;
  flex-direction: column;
  gap: 4px;
