}

.all-settings-run {
  display: flex;
  flex-direction: column;
}

.all-settings-run-name {
  padding-top: 4px;
  font: var(--font-metadata-bold);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

.all-settings-row {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Name left, value right, on one 28 DIP line where they fit: the name gives
   way, with the whole of it in the tooltip; the value is never cut. */
.all-settings-row-line {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  font: var(--font-body-small);
  color: var(--text-primary);
}

.all-settings-row-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.all-settings-row-value {
  flex: 0 0 auto;
  max-width: 60%;
  overflow-wrap: anywhere;
}

.all-settings-row-value--bold {
  font: var(--font-body-small-bold);
}

.all-settings-row-value--muted {
  color: var(--text-secondary);
}

.all-settings-row-tag {
  flex: 0 0 auto;
  width: 64px;
  font: var(--font-metadata);
  color: var(--text-secondary);
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.all-settings-row-note {
  padding: 0 0 4px;
  font: var(--font-metadata);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

/* Two or three filament slots side by side: a grid whose first column is
   the name and whose others, one per slot, line up under the slot heads. */
.all-settings-columns {
  display: flex;
  flex-direction: column;
}

.all-settings-columns-head,
.all-settings-row-line--columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) repeat(var(--all-settings-slots), minmax(0, auto));
  align-items: center;
  gap: 8px;
}

.all-settings-row-line--columns .all-settings-row-value {
  max-width: none;
  text-align: right;
}

.all-settings-column-slot {
  display: flex;
  flex-direction: column;
