  right: auto;
  left: 0;
  min-width: 100%;
}

.all-settings-hint,
.all-settings-note,
.all-settings-own-hint {
  font: var(--font-label);
  color: var(--text-secondary);
}

.all-settings-find {
  display: flex;
  align-items: center;
  gap: 8px;
}

.all-settings-search {
  flex: 1 1 auto;
  min-width: 0;
}

/* The design system's Segmented Control, as the setup screens draw it, for
   any surface: a subtle track holding equal segments, the chosen one filled
   with action/primary. */
.jp-segmented {
  display: flex;
  flex: 0 0 auto;
  box-sizing: border-box;
  height: var(--segmented-height);
  padding: var(--segmented-padding);
  border: var(--segmented-border-width) solid var(--border-subtle);
  border-radius: var(--segmented-radius);
  background: var(--surface-subtle);
}

.jp-segment {
  flex: 1 1 auto;
  height: var(--segmented-segment-height);
  padding: var(--segmented-segment-padding-y) var(--segmented-segment-padding-x);
  border: 0;
  border-radius: var(--segmented-radius);
  background: transparent;
  font: var(--font-label);
  color: var(--text-primary);
  white-space: nowrap;
  cursor: pointer;
}

.jp-segment:hover:enabled,
.jp-segment:active:enabled {
  border: 0;
}

.jp-segment.selected {
  background: var(--action-primary);
  color: var(--action-primary-text);
}

.jp-segment:disabled {
  color: var(--action-disabled-text);
  cursor: default;
}

/* The presets in use, and an object's or a plate's summary: a subtle box. */
.all-settings-presets {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border-radius: var(--radius-medium);
  background: var(--surface-subtle);
}

.all-settings-preset {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.all-settings-preset-label {
  font: var(--font-label);
  color: var(--text-secondary);
}

.all-settings-preset-value {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font: var(--font-body-small);
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

.all-settings-preset-slot {
  display: flex;
  align-items: center;
  gap: 8px;
}

.all-settings-preset-detail {
  display: block;
  font: var(--font-metadata);
  color: var(--text-secondary);
}

.all-settings-object-summary {
  font: var(--font-body-small);
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

/* The design system's Swatch: one filament colour, with a stroke so a
   white filament stays visible. */
.all-settings-swatch {
  flex: 0 0 auto;
  display: inline-block;
  width: var(--swatch-size);
  height: var(--swatch-size);
  border-radius: var(--radius-small);
  background: var(--surface-subtle);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
}

/* Objects that print with settings of their own, which the project view
   cannot show. */
.all-settings-own {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font: var(--font-body-small);
  color: var(--text-primary);
}

.all-settings-groups {
  display: flex;
  flex-direction: column;
}

.all-settings-group {
  border-bottom: 1px solid var(--border-subtle);
}

/* A group's header is a 32 DIP row: the chevron, the name, and on the right
   what the group says about itself ("3 changed", "same as project"). */
.all-settings-group-header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  height: 32px;
  padding: 0;
  border: 0;
  background: none;
  text-align: left;
  color: var(--text-primary);
  cursor: pointer;
}

.all-settings-group-header--empty {
  cursor: default;
}

.all-settings-group-header .jp-icon {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
  color: var(--text-secondary);
}

.all-settings-group-name {
  flex: 0 0 auto;
  font: var(--font-body-small-bold);
  white-space: nowrap;
}

.all-settings-group-summary {
  flex: 1 1 auto;
  min-width: 0;
  font: var(--font-label);
  color: var(--text-secondary);
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The rows sit under the name, past the chevron (icon 16 + gap 8). */
.all-settings-group-rows {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0 0 4px 24px;
}

.all-settings-run {
  display: flex;
  flex-direction: column;
}

.all-settings-run-name {
  padding-top: 4px;
  font: var(--font-metadata-bold);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

.all-settings-row {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Name left, value right, on one 28 DIP line where they fit: the name gives
   way, with the whole of it in the tooltip; the value is never cut. */
.all-settings-row-line {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 28px;
  font: var(--font-body-small);
  color: var(--text-primary);
}

.all-settings-row-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.all-settings-row-value {
  flex: 0 0 auto;
  max-width: 60%;
  overflow-wrap: anywhere;
}

.all-settings-row-value--bold {
  font: var(--font-body-small-bold);
}

.all-settings-row-value--muted {
  color: var(--text-secondary);
}

.all-settings-row-tag {
  flex: 0 0 auto;
  width: 64px;
  font: var(--font-metadata);
  color: var(--text-secondary);
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.all-settings-row-note {
  padding: 0 0 4px;
  font: var(--font-metadata);
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

/* Two or three filament slots side by side: a grid whose first column is
   the name and whose others, one per slot, line up under the slot heads. */
.all-settings-columns {
  display: flex;
  flex-direction: column;
}

.all-settings-columns-head,
.all-settings-row-line--columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) repeat(var(--all-settings-slots), minmax(0, auto));
  align-items: center;
  gap: 8px;
}

.all-settings-row-line--columns .all-settings-row-value {
  max-width: none;
  text-align: right;
}

.all-settings-column-slot {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  padding: 4px 0;
  min-width: 0;
}

.all-settings-column-slot-name {
  font: var(--font-metadata);
  color: var(--text-secondary);
}

.all-settings-column-slot-material {
  font: var(--font-label-bold);
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

/* An object on a plate: its name opens its own view. */
.all-settings-object-link {
  flex: 1 1 auto;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  font: var(--font-label-bold);
  color: var(--action-primary);
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}

.all-settings-object-link:hover {
  color: var(--action-primary-hover);
  text-decoration: underline;
}
'''
open(p,'w').write(s)
